-- ----------------------------
-- Table structure for kb_skills
-- ----------------------------
DROP TABLE IF EXISTS `kb_skills`;
CREATE TABLE `kb_skills`  (
                              `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
                              `workspace_id` bigint(20) NULL DEFAULT NULL COMMENT '工作区id',
                              `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '名称',
                              `description` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '描述',
                              `file_path` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '文件路径',
                              `prompt` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '指令',
                              `status` tinyint(1) NULL DEFAULT NULL COMMENT '状态;0：启用，1：禁用',
                              `valid_flag` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否有效;0：无效，1：有效',
                              `del_flag` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除标志;1：已删除，0：未删除',
                              `create_by` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
                              `creator_id` bigint(20) NULL DEFAULT NULL COMMENT '创建人id',
                              `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                              `update_by` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
                              `updater_id` bigint(20) NULL DEFAULT NULL COMMENT '更新人id',
                              `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
                              `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
                              PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 24 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'skills管理' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of kb_skills
-- ----------------------------
INSERT INTO `kb_skills` VALUES (1, 1001, 'brainstorming', '\"You MUST use this before any creative work - creating features, building components, adding functionality, or modifying behavior. Explores user intent, requirements and design before implementation.\"', '/skills/brainstorming', '# Brainstorming Ideas Into Designs\n\nHelp turn ideas into fully formed designs and specs through natural collaborative dialogue.\n\nStart by understanding the current project context, then ask questions one at a time to refine the idea. Once you understand what you\'re building, present the design and get user approval.\n\n<HARD-GATE>\nDo NOT invoke any implementation skill, write any code, scaffold any project, or take any implementation action until you have presented a design and the user has approved it. This applies to EVERY project regardless of perceived simplicity.\n</HARD-GATE>\n\n## Anti-Pattern: \"This Is Too Simple To Need A Design\"\n\nEvery project goes through this process. A todo list, a single-function utility, a config change — all of them. \"Simple\" projects are where unexamined assumptions cause the most wasted work. The design can be short (a few sentences for truly simple projects), but you MUST present it and get approval.\n\n## Checklist\n\nYou MUST create a task for each of these items and complete them in order:\n\n1. **Explore project context** — check files, docs, recent commits\n2. **Offer visual companion** (if topic will involve visual questions) — this is its own message, not combined with a clarifying question. See the Visual Companion section below.\n3. **Ask clarifying questions** — one at a time, understand purpose/constraints/success criteria\n4. **Propose 2-3 approaches** — with trade-offs and your recommendation\n5. **Present design** — in sections scaled to their complexity, get user approval after each section\n6. **Write design doc** — save to `docs/superpowers/specs/YYYY-MM-DD-<topic>-design.md` and commit\n7. **Spec review loop** — dispatch spec-document-reviewer subagent with precisely crafted review context (never your session history); fix issues and re-dispatch until approved (max 5 iterations, then surface to human)\n8. **User reviews written spec** — ask user to review the spec file before proceeding\n9. **Transition to implementation** — invoke writing-plans skill to create implementation plan\n\n## Process Flow\n\n```dot\ndigraph brainstorming {\n    \"Explore project context\" [shape=box];\n    \"Visual questions ahead?\" [shape=diamond];\n    \"Offer Visual Companion\\n(own message, no other content)\" [shape=box];\n    \"Ask clarifying questions\" [shape=box];\n    \"Propose 2-3 approaches\" [shape=box];\n    \"Present design sections\" [shape=box];\n    \"User approves design?\" [shape=diamond];\n    \"Write design doc\" [shape=box];\n    \"Spec review loop\" [shape=box];\n    \"Spec review passed?\" [shape=diamond];\n    \"User reviews spec?\" [shape=diamond];\n    \"Invoke writing-plans skill\" [shape=doublecircle];\n\n    \"Explore project context\" -> \"Visual questions ahead?\";\n    \"Visual questions ahead?\" -> \"Offer Visual Companion\\n(own message, no other content)\" [label=\"yes\"];\n    \"Visual questions ahead?\" -> \"Ask clarifying questions\" [label=\"no\"];\n    \"Offer Visual Companion\\n(own message, no other content)\" -> \"Ask clarifying questions\";\n    \"Ask clarifying questions\" -> \"Propose 2-3 approaches\";\n    \"Propose 2-3 approaches\" -> \"Present design sections\";\n    \"Present design sections\" -> \"User approves design?\";\n    \"User approves design?\" -> \"Present design sections\" [label=\"no, revise\"];\n    \"User approves design?\" -> \"Write design doc\" [label=\"yes\"];\n    \"Write design doc\" -> \"Spec review loop\";\n    \"Spec review loop\" -> \"Spec review passed?\";\n    \"Spec review passed?\" -> \"Spec review loop\" [label=\"issues found,\\nfix and re-dispatch\"];\n    \"Spec review passed?\" -> \"User reviews spec?\" [label=\"approved\"];\n    \"User reviews spec?\" -> \"Write design doc\" [label=\"changes requested\"];\n    \"User reviews spec?\" -> \"Invoke writing-plans skill\" [label=\"approved\"];\n}\n```\n\n**The terminal state is invoking writing-plans.** Do NOT invoke frontend-design, mcp-builder, or any other implementation skill. The ONLY skill you invoke after brainstorming is writing-plans.\n\n## The Process\n\n**Understanding the idea:**\n\n- Check out the current project state first (files, docs, recent commits)\n- Before asking detailed questions, assess scope: if the request describes multiple independent subsystems (e.g., \"build a platform with chat, file storage, billing, and analytics\"), flag this immediately. Don\'t spend questions refining details of a project that needs to be decomposed first.\n- If the project is too large for a single spec, help the user decompose into sub-projects: what are the independent pieces, how do they relate, what order should they be built? Then brainstorm the first sub-project through the normal design flow. Each sub-project gets its own spec → plan → implementation cycle.\n- For appropriately-scoped projects, ask questions one at a time to refine the idea\n- Prefer multiple choice questions when possible, but open-ended is fine too\n- Only one question per message - if a topic needs more exploration, break it into multiple questions\n- Focus on understanding: purpose, constraints, success criteria\n\n**Exploring approaches:**\n\n- Propose 2-3 different approaches with trade-offs\n- Present options conversationally with your recommendation and reasoning\n- Lead with your recommended option and explain why\n\n**Presenting the design:**\n\n- Once you believe you understand what you\'re building, present the design\n- Scale each section to its complexity: a few sentences if straightforward, up to 200-300 words if nuanced\n- Ask after each section whether it looks right so far\n- Cover: architecture, components, data flow, error handling, testing\n- Be ready to go back and clarify if something doesn\'t make sense\n\n**Design for isolation and clarity:**\n\n- Break the system into smaller units that each have one clear purpose, communicate through well-defined interfaces, and can be understood and tested independently\n- For each unit, you should be able to answer: what does it do, how do you use it, and what does it depend on?\n- Can someone understand what a unit does without reading its internals? Can you change the internals without breaking consumers? If not, the boundaries need work.\n- Smaller, well-bounded units are also easier for you to work with - you reason better about code you can hold in context at once, and your edits are more reliable when files are focused. When a file grows large, that\'s often a signal that it\'s doing too much.\n\n**Working in existing codebases:**\n\n- Explore the current structure before proposing changes. Follow existing patterns.\n- Where existing code has problems that affect the work (e.g., a file that\'s grown too large, unclear boundaries, tangled responsibilities), include targeted improvements as part of the design - the way a good developer improves code they\'re working in.\n- Don\'t propose unrelated refactoring. Stay focused on what serves the current goal.\n\n## After the Design\n\n**Documentation:**\n\n- Write the validated design (spec) to `docs/superpowers/specs/YYYY-MM-DD-<topic>-design.md`\n  - (User preferences for spec location override this default)\n- Use elements-of-style:writing-clearly-and-concisely skill if available\n- Commit the design document to git\n\n**Spec Review Loop:**\nAfter writing the spec document:\n\n1. Dispatch spec-document-reviewer subagent (see spec-document-reviewer-prompt.md)\n2. If Issues Found: fix, re-dispatch, repeat until Approved\n3. If loop exceeds 5 iterations, surface to human for guidance\n\n**User Review Gate:**\nAfter the spec review loop passes, ask the user to review the written spec before proceeding:\n\n> \"Spec written and committed to `<path>`. Please review it and let me know if you want to make any changes before we start writing out the implementation plan.\"\n\nWait for the user\'s response. If they request changes, make them and re-run the spec review loop. Only proceed once the user approves.\n\n**Implementation:**\n\n- Invoke the writing-plans skill to create a detailed implementation plan\n- Do NOT invoke any other skill. writing-plans is the next step.\n\n## Key Principles\n\n- **One question at a time** - Don\'t overwhelm with multiple questions\n- **Multiple choice preferred** - Easier to answer than open-ended when possible\n- **YAGNI ruthlessly** - Remove unnecessary features from all designs\n- **Explore alternatives** - Always propose 2-3 approaches before settling\n- **Incremental validation** - Present design, get approval before moving on\n- **Be flexible** - Go back and clarify when something doesn\'t make sense\n\n## Visual Companion\n\nA browser-based companion for showing mockups, diagrams, and visual options during brainstorming. Available as a tool — not a mode. Accepting the companion means it\'s available for questions that benefit from visual treatment; it does NOT mean every question goes through the browser.\n\n**Offering the companion:** When you anticipate that upcoming questions will involve visual content (mockups, layouts, diagrams), offer it once for consent:\n> \"Some of what we\'re working on might be easier to explain if I can show it to you in a web browser. I can put together mockups, diagrams, comparisons, and other visuals as we go. This feature is still new and can be token-intensive. Want to try it? (Requires opening a local URL)\"\n\n**This offer MUST be its own message.** Do not combine it with clarifying questions, context summaries, or any other content. The message should contain ONLY the offer above and nothing else. Wait for the user\'s response before continuing. If they decline, proceed with text-only brainstorming.\n\n**Per-question decision:** Even after the user accepts, decide FOR EACH QUESTION whether to use the browser or the terminal. The test: **would the user understand this better by seeing it than reading it?**\n\n- **Use the browser** for content that IS visual — mockups, wireframes, layout comparisons, architecture diagrams, side-by-side visual designs\n- **Use the terminal** for content that is text — requirements questions, conceptual choices, tradeoff lists, A/B/C/D text options, scope decisions\n\nA question about a UI topic is not automatically a visual question. \"What does personality mean in this context?\" is a conceptual question — use the terminal. \"Which wizard layout works better?\" is a visual question — use the browser.\n\nIf they agree to the companion, read the detailed guide before proceeding:\n`skills/brainstorming/visual-companion.md`', 1, 1, 0, '吴同', 2, '2026-06-24 17:19:44', '吴同', NULL, '2026-06-24 17:19:44', NULL);
                                INSERT INTO `kb_skills` VALUES (2, 1001, 'chinese-only-output', '强制后续输出使用中文的语言约束技能。用于用户明确要求“全程中文回答”“后续都用中文输出”“不要英文说明”“代码注释也必须中文”等场景。启用后，所有自然语言说明、提问、总结、评审意见、状态更新与代码注释都必须使用中文；代码、命令、路径、配置键名、接口字段名以及日志或报错原文保持原样，除非用户明确要求其他语言。', '/skills/chinese-only-output', '# Chinese Only Output\n\n## 核心规则\n\n启用本技能后，默认将中文作为唯一输出语言。\n\n必须使用中文的内容：\n\n- 所有自然语言说明\n- 所有提问与澄清\n- 所有总结、计划、状态更新、评审意见\n- 所有代码注释\n\n保留原样的内容：\n\n- 代码标识符\n- 终端命令\n- 文件路径\n- 配置键名\n- 接口字段名\n- 日志原文\n- 报错原文\n- 第三方协议要求固定为英文的字面量\n\n## 执行要求\n\n遵循下面的输出约束：\n\n1. 先用中文表达结论、说明与推理。\n2. 如必须附带英文原文，只提供最小必要范围，并先给中文说明。\n3. 不要为了满足中文要求而改写必须精确保留的命令、路径、字段名、协议值或错误文本。\n4. 编写或修改代码时，新增注释与修改后的注释必须为中文。\n5. 不强制将变量名、函数名、类名、数据库字段名改为中文；保持项目既有命名约定。\n\n## 冲突处理\n\n若出现以下情况，按此顺序处理：\n\n1. 用户明确要求其他语言时，按用户要求临时切换。\n2. 外部系统、协议、编译器或工具要求英文固定文本时，保留原文。\n3. 其余所有可自然表达的文本一律使用中文。\n\n## 典型触发语\n\n以下表达都应触发本技能：\n\n- 后续都用中文回答\n- 默认中文输出\n- 不要英文说明\n- 请全程使用中文\n- 代码注释也要中文\n\n## 自检清单\n\n输出前快速检查：\n\n- 是否有可以改成中文的自然语言仍残留为英文\n- 代码注释是否全部为中文\n- 命令、路径、字段名、日志原文是否被错误翻译', 1, 1, 0, '吴同', 2, '2026-06-24 17:19:44', '吴同', NULL, '2026-06-24 17:19:44', NULL);
INSERT INTO `kb_skills` VALUES (3, 1001, 'dispatching-parallel-agents', 'Use when facing 2+ independent tasks that can be worked on without shared state or sequential dependencies', '/skills/dispatching-parallel-agents', '# Dispatching Parallel Agents\n\n## Overview\n\nYou delegate tasks to specialized agents with isolated context. By precisely crafting their instructions and context, you ensure they stay focused and succeed at their task. They should never inherit your session\'s context or history — you construct exactly what they need. This also preserves your own context for coordination work.\n\nWhen you have multiple unrelated failures (different test files, different subsystems, different bugs), investigating them sequentially wastes time. Each investigation is independent and can happen in parallel.\n\n**Core principle:** Dispatch one agent per independent problem domain. Let them work concurrently.\n\n## When to Use\n\n```dot\ndigraph when_to_use {\n    \"Multiple failures?\" [shape=diamond];\n    \"Are they independent?\" [shape=diamond];\n    \"Single agent investigates all\" [shape=box];\n    \"One agent per problem domain\" [shape=box];\n    \"Can they work in parallel?\" [shape=diamond];\n    \"Sequential agents\" [shape=box];\n    \"Parallel dispatch\" [shape=box];\n\n    \"Multiple failures?\" -> \"Are they independent?\" [label=\"yes\"];\n    \"Are they independent?\" -> \"Single agent investigates all\" [label=\"no - related\"];\n    \"Are they independent?\" -> \"Can they work in parallel?\" [label=\"yes\"];\n    \"Can they work in parallel?\" -> \"Parallel dispatch\" [label=\"yes\"];\n    \"Can they work in parallel?\" -> \"Sequential agents\" [label=\"no - shared state\"];\n}\n```\n\n**Use when:**\n- 3+ test files failing with different root causes\n- Multiple subsystems broken independently\n- Each problem can be understood without context from others\n- No shared state between investigations\n\n**Don\'t use when:**\n- Failures are related (fix one might fix others)\n- Need to understand full system state\n- Agents would interfere with each other\n\n## The Pattern\n\n### 1. Identify Independent Domains\n\nGroup failures by what\'s broken:\n- File A tests: Tool approval flow\n- File B tests: Batch completion behavior\n- File C tests: Abort functionality\n\nEach domain is independent - fixing tool approval doesn\'t affect abort tests.\n\n### 2. Create Focused Agent Tasks\n\nEach agent gets:\n- **Specific scope:** One test file or subsystem\n- **Clear goal:** Make these tests pass\n- **Constraints:** Don\'t change other code\n- **Expected output:** Summary of what you found and fixed\n\n### 3. Dispatch in Parallel\n\n```typescript\n// In Claude Code / AI environment\nTask(\"Fix agent-tool-abort.test.ts failures\")\nTask(\"Fix batch-completion-behavior.test.ts failures\")\nTask(\"Fix tool-approval-race-conditions.test.ts failures\")\n// All three run concurrently\n```\n\n### 4. Review and Integrate\n\nWhen agents return:\n- Read each summary\n- Verify fixes don\'t conflict\n- Run full test suite\n- Integrate all changes\n\n## Agent Prompt Structure\n\nGood agent prompts are:\n1. **Focused** - One clear problem domain\n2. **Self-contained** - All context needed to understand the problem\n3. **Specific about output** - What should the agent return?\n\n```markdown\nFix the 3 failing tests in src/agents/agent-tool-abort.test.ts:\n\n1. \"should abort tool with partial output capture\" - expects \'interrupted at\' in message\n2. \"should handle mixed completed and aborted tools\" - fast tool aborted instead of completed\n3. \"should properly track pendingToolCount\" - expects 3 results but gets 0\n\nThese are timing/race condition issues. Your task:\n\n1. Read the test file and understand what each test verifies\n2. Identify root cause - timing issues or actual bugs?\n3. Fix by:\n   - Replacing arbitrary timeouts with event-based waiting\n   - Fixing bugs in abort implementation if found\n   - Adjusting test expectations if testing changed behavior\n\nDo NOT just increase timeouts - find the real issue.\n\nReturn: Summary of what you found and what you fixed.\n```\n\n## Common Mistakes\n\n**❌ Too broad:** \"Fix all the tests\" - agent gets lost\n**✅ Specific:** \"Fix agent-tool-abort.test.ts\" - focused scope\n\n**❌ No context:** \"Fix the race condition\" - agent doesn\'t know where\n**✅ Context:** Paste the error messages and test names\n\n**❌ No constraints:** Agent might refactor everything\n**✅ Constraints:** \"Do NOT change production code\" or \"Fix tests only\"\n\n**❌ Vague output:** \"Fix it\" - you don\'t know what changed\n**✅ Specific:** \"Return summary of root cause and changes\"\n\n## When NOT to Use\n\n**Related failures:** Fixing one might fix others - investigate together first\n**Need full context:** Understanding requires seeing entire system\n**Exploratory debugging:** You don\'t know what\'s broken yet\n**Shared state:** Agents would interfere (editing same files, using same resources)\n\n## Real Example from Session\n\n**Scenario:** 6 test failures across 3 files after major refactoring\n\n**Failures:**\n- agent-tool-abort.test.ts: 3 failures (timing issues)\n- batch-completion-behavior.test.ts: 2 failures (tools not executing)\n- tool-approval-race-conditions.test.ts: 1 failure (execution count = 0)\n\n**Decision:** Independent domains - abort logic separate from batch completion separate from race conditions\n\n**Dispatch:**\n```\nAgent 1 → Fix agent-tool-abort.test.ts\nAgent 2 → Fix batch-completion-behavior.test.ts\nAgent 3 → Fix tool-approval-race-conditions.test.ts\n```\n\n**Results:**\n- Agent 1: Replaced timeouts with event-based waiting\n- Agent 2: Fixed event structure bug (threadId in wrong place)\n- Agent 3: Added wait for async tool execution to complete\n\n**Integration:** All fixes independent, no conflicts, full suite green\n\n**Time saved:** 3 problems solved in parallel vs sequentially\n\n## Key Benefits\n\n1. **Parallelization** - Multiple investigations happen simultaneously\n2. **Focus** - Each agent has narrow scope, less context to track\n3. **Independence** - Agents don\'t interfere with each other\n4. **Speed** - 3 problems solved in time of 1\n\n## Verification\n\nAfter agents return:\n1. **Review each summary** - Understand what changed\n2. **Check for conflicts** - Did agents edit same code?\n3. **Run full suite** - Verify all fixes work together\n4. **Spot check** - Agents can make systematic errors\n\n## Real-World Impact\n\nFrom debugging session (2025-10-03):\n- 6 failures across 3 files\n- 3 agents dispatched in parallel\n- All investigations completed concurrently\n- All fixes integrated successfully\n- Zero conflicts between agent changes', 1, 1, 0, '吴同', 2, '2026-06-24 17:19:44', '吴同', NULL, '2026-06-24 17:19:44', NULL);
INSERT INTO `kb_skills` VALUES (4, 1001, 'executing-plans', 'Use when you have a written implementation plan to execute in a separate session with review checkpoints', '/skills/executing-plans', '# Executing Plans\n\n## Overview\n\nLoad plan, review critically, execute all tasks, report when complete.\n\n**Announce at start:** \"I\'m using the executing-plans skill to implement this plan.\"\n\n**Note:** Tell your human partner that Superpowers works much better with access to subagents. The quality of its work will be significantly higher if run on a platform with subagent support (such as Claude Code or Codex). If subagents are available, use superpowers:subagent-driven-development instead of this skill.\n\n## The Process\n\n### Step 1: Load and Review Plan\n1. Read plan file\n2. Review critically - identify any questions or concerns about the plan\n3. If concerns: Raise them with your human partner before starting\n4. If no concerns: Create TodoWrite and proceed\n\n### Step 2: Execute Tasks\n\nFor each task:\n1. Mark as in_progress\n2. Follow each step exactly (plan has bite-sized steps)\n3. Run verifications as specified\n4. Mark as completed\n\n### Step 3: Complete Development\n\nAfter all tasks complete and verified:\n- Announce: \"I\'m using the finishing-a-development-branch skill to complete this work.\"\n- **REQUIRED SUB-SKILL:** Use superpowers:finishing-a-development-branch\n- Follow that skill to verify tests, present options, execute choice\n\n## When to Stop and Ask for Help\n\n**STOP executing immediately when:**\n- Hit a blocker (missing dependency, test fails, instruction unclear)\n- Plan has critical gaps preventing starting\n- You don\'t understand an instruction\n- Verification fails repeatedly\n\n**Ask for clarification rather than guessing.**\n\n## When to Revisit Earlier Steps\n\n**Return to Review (Step 1) when:**\n- Partner updates the plan based on your feedback\n- Fundamental approach needs rethinking\n\n**Don\'t force through blockers** - stop and ask.\n\n## Remember\n- Review plan critically first\n- Follow plan steps exactly\n- Don\'t skip verifications\n- Reference skills when plan says to\n- Stop when blocked, don\'t guess\n- Never start implementation on main/master branch without explicit user consent\n\n## Integration\n\n**Required workflow skills:**\n- **superpowers:using-git-worktrees** - REQUIRED: Set up isolated workspace before starting\n- **superpowers:writing-plans** - Creates the plan this skill executes\n- **superpowers:finishing-a-development-branch** - Complete development after all tasks', 1, 1, 0, '吴同', 2, '2026-06-24 17:19:44', '吴同', NULL, '2026-06-24 17:19:44', NULL);
INSERT INTO `kb_skills` VALUES (5, 1001, 'feature-clarify', 'Use when turning a one-sentence feature or backlog item into a clarified question list and lightweight specification before any implementation work.', '/skills/feature-clarify', '# /feature-clarify Skill\r\n\r\n## Overview\r\n\r\nThis skill guides the agent to take an initial feature request or backlog item and turn it into:\r\n\r\n- A **reviewable clarification question list** (with explicit options and selected answers)\r\n- A **lightweight functional specification draft** (no implementation details, no code)\r\n\r\nIt is designed to work together with the project command definition in `.cursor/commands/01-feature-clarify.md`.\r\n\r\n## When to Use\r\n\r\nUse this skill when:\r\n\r\n- The user invokes the `/feature-clarify` command (or equivalent) with:\r\n  - One-sentence requirement\r\n  - Business background\r\n  - Current state / pain points\r\n  - Constraints (time / tech / compliance / compatibility)\r\n  - Related systems / modules\r\n  - Target users / roles (if known)\r\n  - Success criteria / acceptance criteria (if known)\r\n  - Priority / urgency\r\n- You need to **clarify the requirement before any design/implementation work**.\r\n- You want a **structured, review-ready document** that can later be used to generate PRD, designs, or implementation plans.\r\n\r\nIf the user is already asking for detailed implementation steps or code, redirect back to clarification first using this skill.\r\n\r\n## Input Expectations\r\n\r\nFrom the user (via command or chat):\r\n\r\n- One-sentence requirement\r\n- Business background\r\n- Current state / pain points\r\n- Constraints (time / technology / compliance / compatibility)\r\n- Related systems / modules (if any)\r\n- Target users / roles (if known)\r\n- Success criteria / acceptance criteria (if known)\r\n- Priority / urgency (P0 / P1 / P2 or similar)\r\n\r\nIf any of these are missing, do **not** block; proceed with what you have and highlight missing items in the clarification output.\r\n\r\nAdditionally, ask (if not provided):\r\n\r\n- A **feature identifier** like `FEAT-123` (or agree on a placeholder such as `FEAT-xxx`) to determine the target documentation path:\r\n  - `docs/features/FEAT-xxx/01-clarification.md`\r\n\r\n## High-Level Workflow\r\n\r\nFollow this workflow whenever this skill is used:\r\n\r\n1. **Parse and summarize inputs**\r\n   - Restate the one-sentence requirement.\r\n   - Summarize background, pain points, and constraints in your own words.\r\n\r\n2. **Collect structured answers via interactive questions**\r\n   - Use the AskQuestion tool (if available) to present **batched multiple-choice questions**.\r\n   - Prefer 3–7 questions per batch to avoid overwhelming the user.\r\n   - For each critical question:\r\n     - Mark it as **【单选】** or **【多选】**.\r\n     - Provide 2–4 options labeled A/B/C/D.\r\n     - Reserve option D / last option as “自定义：xxxx” when appropriate.\r\n\r\n3. **Iterate through 2–3 batches of questions**\r\n   - **Batch 1 – Scope & boundaries**\r\n   - **Batch 2 – Users, roles & permissions**\r\n   - **Batch 3 – Flows, edge cases & non-functionals**\r\n   - After each batch:\r\n     - Merge user selections into an internal “answers state”.\r\n     - Decide whether more batches are needed based on remaining uncertainties.\r\n\r\n4. **Synthesize outputs into a structured clarification document**\r\n   - Section 1: Clarification question list\r\n   - Section 2: Functional spec draft\r\n   - Section 3: Key decisions & risks\r\n   - Section 4: Gate judgment (READY_FOR_NEXT / NOT_READY)\r\n\r\n5. **Persist or present the result**\r\n   - In **Agent mode** with file access:\r\n     - Write or update `docs/features/FEAT-xxx/01-clarification.md`.\r\n   - In **Ask/Plan modes** or read-only contexts:\r\n     - Present the full document as markdown in the chat and clearly indicate the target file path for the user to copy.\r\n\r\n## Question Design (Batches and Examples)\r\n\r\nYou MUST respect the command’s requirement:\r\n\r\n- At most **15** clarification questions.\r\n- Each key question should have **2–4 options** and be marked as **【单选】** or **【多选】**.\r\n\r\n### Batch 1 – Scope & Boundaries\r\n\r\nFocus on “what is / is not included” and critical constraints.\r\n\r\nTypical questions (adapt as needed to the specific feature):\r\n\r\n1. **【单选】本期要解决的核心目标是哪一类？**\r\n   - A) 新功能（从无到有）\r\n   - B) 现有功能增强 / 重构\r\n   - C) 运营配置 / 规则变更\r\n   - D) 其它：自定义说明\r\n\r\n2. **【多选】本期 in-scope 的范围包含哪些？**\r\n   - A) 后端接口 / 服务能力\r\n   - B) 前端页面 / 交互\r\n   - C) 任务调度 / 异步流程\r\n   - D) 数据结构 / 表结构调整\r\n   - E) 权限 / 审计 / 安全控制\r\n   - F) 其它：自定义说明\r\n\r\n3. **【多选】本期明确 out-of-scope 的内容有哪些？**\r\n   - A) 跨系统集成\r\n   - B) 报表 / BI 展示\r\n   - C) 历史数据迁移\r\n   - D) 复杂自动化策略 / 风控\r\n   - E) 其它：自定义说明\r\n\r\n4. **【单选】时间与优先级约束？**\r\n   - A) P0：必须在当前迭代上线\r\n   - B) P1：本季度内完成\r\n   - C) P2：有空就做 / 机会型\r\n   - D) 由你补充更具体的时间窗口\r\n\r\n### Batch 2 – Users, Roles & Permissions\r\n\r\nClarify **who** can do **what**.\r\n\r\n5. **【多选】涉及的主要用户角色有哪些？**\r\n   - A) 业务运营 / 配置人员\r\n   - B) 开发 / 技术人员\r\n   - C) 管理员 / 系统 OWNER\r\n   - D) 终端业务用户（如普通员工 / 客户）\r\n   - E) 其它：自定义说明\r\n\r\n6. **【多选】本期是否需要区分不同角色的操作权限？**\r\n   - A) 仅区分“可见 / 不可见”\r\n   - B) 区分“查看 / 新增 / 编辑 / 删除”\r\n   - C) 区分“配置 / 审批 / 执行”\r\n   - D) 不做权限细分，由上游系统控制\r\n\r\n7. **【多选】需要审计的操作类型？**\r\n   - A) 新增 / 编辑 / 删除\r\n   - B) 启用 / 禁用 / 状态切换\r\n   - C) 重要测试 /校验操作（如连接测试、风控试跑）\r\n   - D) 敏感数据查看 / 导出\r\n   - E) 其它：自定义说明\r\n\r\n### Batch 3 – Flows, Edge Cases & Non-Functional\r\n\r\n8. **【多选】本期必须覆盖的主流程有哪些？**\r\n   - A) 新增 / 创建\r\n   - B) 编辑 / 更新\r\n   - C) 启用 / 禁用\r\n   - D) 查询 / 筛选 / 列表展示\r\n   - E) 导出 / 下载\r\n   - F) 其它：自定义说明\r\n\r\n9. **【多选】优先考虑的边界 / 异常场景？**\r\n   - A) 删除 / 禁用被引用中的对象\r\n   - B) 外部依赖失败（超时、网络异常、第三方错误）\r\n   - C) 权限不足 / 未登录\r\n   - D) 并发修改 / 冲突\r\n   - E) 输入参数非法 / 校验失败\r\n   - F) 其它：自定义说明\r\n\r\n10. **【多选】本期最重要的非功能需求是哪几类？**\r\n    - A) 性能（响应时间、吞吐量）\r\n    - B) 可用性 / 稳定性\r\n    - C) 安全（权限、敏感数据保护）\r\n    - D) 审计 / 可追溯\r\n    - E) 可观测性（日志、指标、告警）\r\n    - F) 其它：自定义说明\r\n\r\nYou may adjust wording and options to fit the domain, but keep the **structure** (ids, single vs multi-select, 2–4 options with a customizable choice).\r\n\r\n## Using AskQuestion (Interactive Form)\r\n\r\nWhen AskQuestion is available, use it to present the questions above in 2–3 batches.\r\n\r\nExample (pseudo-structure, not exact JSON):\r\n\r\n```markdown\r\nAskQuestion:\r\n  title: \"feature-clarify 关键澄清\"\r\n  questions:\r\n    - id: \"q_scope_type\"\r\n      prompt: \"1）本期要解决的核心目标是哪一类？\"\r\n      options:\r\n        - { id: \"A\", label: \"A) 新功能（从无到有）\" }\r\n        - { id: \"B\", label: \"B) 现有功能增强 / 重构\" }\r\n        - { id: \"C\", label: \"C) 运营配置 / 规则变更\" }\r\n        - { id: \"D\", label: \"D) 其它：我在后续回答里说明\" }\r\n    - id: \"q_in_scope\"\r\n      prompt: \"2）本期 in-scope 的范围包含哪些？【可多选】\"\r\n      allow_multiple: true\r\n      options:\r\n        - { id: \"A\", label: \"A) 后端接口 / 服务能力\" }\r\n        - { id: \"B\", label: \"B) 前端页面 / 交互\" }\r\n        - { id: \"C\", label: \"C) 任务调度 / 异步流程\" }\r\n        - { id: \"D\", label: \"D) 数据结构 / 表结构调整\" }\r\n        - { id: \"E\", label: \"E) 权限 / 审计 / 安全控制\" }\r\n        - { id: \"F\", label: \"F) 其它：我在后续回答里说明\" }\r\n```\r\n\r\nIf AskQuestion is not available, ask the same questions conversationally and instruct the user to reply like:\r\n\r\n- `1 选 B，2 选 A+C+E，3 选 D：xxxx`\r\n\r\n## Generating the Clarification Output\r\n\r\nThe final output MUST follow the structure defined in `.cursor/commands/01-feature-clarify.md`:\r\n\r\n1. **澄清问题清单（按优先级，最多 15 个）**\r\n   - 列出所有关键问题，标明：\r\n     - 【单选】或【多选】\r\n     - 选项 A/B/C/D 的全文\r\n     - 用户的实际选择（如：“已选：B、D（自定义：……）”）\r\n   - 按优先级排序（高优先级痛点 / 影响范围大的问题排前）。\r\n\r\n2. **功能规格草案**\r\n   - 目标 / 非目标（in-scope / out-of-scope 明确）\r\n   - 用户角色与权限（用简易权限矩阵表示谁能看 / 改 / 删 / 导出等）\r\n   - 主流程（≥ 1 条，如新增、编辑、启用 / 禁用、测试、筛选等）\r\n   - 边界 / 异常（≥ 10 条，覆盖删除 / 禁用被引用、外部失败、超时、敏感字段展示等）\r\n   - 非功能需求（性能 / 安全 / 审计 / 可观测性）\r\n\r\n3. **关键决策与风险**\r\n   - 对关键设计 / 取舍给出备选：\r\n     - A) 保守方案\r\n     - B) 进取方案\r\n     - C) 折中方案\r\n   - 允许用户直接用“选 B”或“都不选，我要 D：xxxx”的方式拍板。\r\n\r\n4. **Gate（READY_FOR_NEXT / NOT_READY）**\r\n   - 按命令文件中的 Gate 规则进行判断：\r\n     1. in-scope / out-of-scope 明确\r\n     2. 权限矩阵草案明确（谁能看 / 改 / 删 / 导出等）\r\n     3. 主流程 ≥ 1 条\r\n     4. 边界 / 异常 ≥ 10 条\r\n     5. 待确认项 ≤ 5，且每一项都有清晰的单选 / 多选备选方案\r\n     6. 成功标准 / 验收口径已定义（至少 1 条可验证标准）\r\n   - 若全部满足：标记为 `READY_FOR_NEXT`，并在末尾建议进入 `/prd-generate`。\r\n   - 否则：标记为 `NOT_READY`，列出阻塞项与建议补充的问题。\r\n\r\n### Markdown Template Suggestion\r\n\r\nWhen generating the final document, you can follow this markdown layout:\r\n\r\n```markdown\r\n1) 澄清问题清单\r\n   1.1 【单选】问题标题……\r\n       - A) 选项 A 文案\r\n       - B) 选项 B 文案\r\n       - C) 选项 C 文案\r\n       - D) 选项 D 文案\r\n       - 已选：B\r\n\r\n   1.2 【多选】问题标题……\r\n       - A) ...\r\n       - B) ...\r\n       - C) ...\r\n       - 已选：A、C（D：自定义说明……）\r\n\r\n2) 功能规格草案\r\n   - 目标（in-scope）\r\n   - 非目标（out-of-scope）\r\n   - 用户角色与权限\r\n   - 主流程\r\n   - 边界 / 异常\r\n   - 非功能需求\r\n\r\n3) 关键决策与风险\r\n   - 决策点 1：A/B/C 方案 + 你的推荐\r\n   - 决策点 2：……\r\n\r\n4) Gate 判定\r\n   - Gate 状态：READY_FOR_NEXT / NOT_READY\r\n   - 检查项说明\r\n   - 阻塞项（如有）\r\n   - 下一步建议（如：进入 `/prd-generate`）\r\n```\r\n\r\n## Integrating with Documentation\r\n\r\nWhen running in a context that allows file edits:\r\n\r\n1. 确认本次澄清对应的 `FEAT` 编号（如 `FEAT-123`）。\r\n2. 计算目标路径：`docs/features/FEAT-123/01-clarification.md`。\r\n3. 若文件不存在：\r\n   - 创建目录 `docs/features/FEAT-123/`。\r\n   - 创建 `01-clarification.md` 并写入完整澄清文档。\r\n4. 若文件已存在：\r\n   - 视情况选择：\r\n     - 覆盖整个文件为最新版本，或\r\n     - 在文件末尾追加“本次澄清版本（日期+时间）”区块。\r\n5. 在聊天回复中始终：\r\n   - 明确给出 Gate 状态。\r\n   - 明确给出目标文件路径。\r\n   - 简要列出阻塞项（若 NOT_READY）。\r\n\r\nIn read-only modes, skip file writes and instead present the full markdown plus the **recommended file path** so the user can copy-paste.\r\n\r\n## Notes and Constraints\r\n\r\n- 不要编造关键业务规则；对于不确定的业务细节，优先用“选项 + 让用户拍板”的方式表达。\r\n- 总问题数控制在 15 个以内，且分批提出，避免用户一次性处理过多信息。\r\n- 输出语言默认为中文，分点编号，结构稳定，便于后续 PRD / 设计 / 开发复用。\r\n- 在整个流程中，始终把用户的决策（选项）显式写入澄清文档，避免再次口头同步。', 1, 1, 0, '吴同', 2, '2026-06-24 17:19:44', '吴同', NULL, '2026-06-24 17:19:44', NULL);
INSERT INTO `kb_skills` VALUES (6, 1001, 'finishing-a-development-branch', 'Use when implementation is complete, all tests pass, and you need to decide how to integrate the work - guides completion of development work by presenting structured options for merge, PR, or cleanup', '/skills/finishing-a-development-branch', '# Finishing a Development Branch\n\n## Overview\n\nGuide completion of development work by presenting clear options and handling chosen workflow.\n\n**Core principle:** Verify tests → Present options → Execute choice → Clean up.\n\n**Announce at start:** \"I\'m using the finishing-a-development-branch skill to complete this work.\"\n\n## The Process\n\n### Step 1: Verify Tests\n\n**Before presenting options, verify tests pass:**\n\n```bash\n# Run project\'s test suite\nnpm test / cargo test / pytest / go test ./...\n```\n\n**If tests fail:**\n```\nTests failing (<N> failures). Must fix before completing:\n\n[Show failures]\n\nCannot proceed with merge/PR until tests pass.\n```\n\nStop. Don\'t proceed to Step 2.\n\n**If tests pass:** Continue to Step 2.\n\n### Step 2: Determine Base Branch\n\n```bash\n# Try common base branches\ngit merge-base HEAD main 2>/dev/null || git merge-base HEAD master 2>/dev/null\n```\n\nOr ask: \"This branch split from main - is that correct?\"\n\n### Step 3: Present Options\n\nPresent exactly these 4 options:\n\n```\nImplementation complete. What would you like to do?\n\n1. Merge back to <base-branch> locally\n2. Push and create a Pull Request\n3. Keep the branch as-is (I\'ll handle it later)\n4. Discard this work\n\nWhich option?\n```\n\n**Don\'t add explanation** - keep options concise.\n\n### Step 4: Execute Choice\n\n#### Option 1: Merge Locally\n\n```bash\n# Switch to base branch\ngit checkout <base-branch>\n\n# Pull latest\ngit pull\n\n# Merge feature branch\ngit merge <feature-branch>\n\n# Verify tests on merged result\n<test command>\n\n# If tests pass\ngit branch -d <feature-branch>\n```\n\nThen: Cleanup worktree (Step 5)\n\n#### Option 2: Push and Create PR\n\n```bash\n# Push branch\ngit push -u origin <feature-branch>\n\n# Create PR\ngh pr create --title \"<title>\" --body \"$(cat <<\'EOF\'\n## Summary\n<2-3 bullets of what changed>\n\n## Test Plan\n- [ ] <verification steps>\nEOF\n)\"\n```\n\nThen: Cleanup worktree (Step 5)\n\n#### Option 3: Keep As-Is\n\nReport: \"Keeping branch <name>. Worktree preserved at <path>.\"\n\n**Don\'t cleanup worktree.**\n\n#### Option 4: Discard\n\n**Confirm first:**\n```\nThis will permanently delete:\n- Branch <name>\n- All commits: <commit-list>\n- Worktree at <path>\n\nType \'discard\' to confirm.\n```\n\nWait for exact confirmation.\n\nIf confirmed:\n```bash\ngit checkout <base-branch>\ngit branch -D <feature-branch>\n```\n\nThen: Cleanup worktree (Step 5)\n\n### Step 5: Cleanup Worktree\n\n**For Options 1, 2, 4:**\n\nCheck if in worktree:\n```bash\ngit worktree list | grep $(git branch --show-current)\n```\n\nIf yes:\n```bash\ngit worktree remove <worktree-path>\n```\n\n**For Option 3:** Keep worktree.\n\n## Quick Reference\n\n| Option | Merge | Push | Keep Worktree | Cleanup Branch |\n|--------|-------|------|---------------|----------------|\n| 1. Merge locally | ✓ | - | - | ✓ |\n| 2. Create PR | - | ✓ | ✓ | - |\n| 3. Keep as-is | - | - | ✓ | - |\n| 4. Discard | - | - | - | ✓ (force) |\n\n## Common Mistakes\n\n**Skipping test verification**\n- **Problem:** Merge broken code, create failing PR\n- **Fix:** Always verify tests before offering options\n\n**Open-ended questions**\n- **Problem:** \"What should I do next?\" → ambiguous\n- **Fix:** Present exactly 4 structured options\n\n**Automatic worktree cleanup**\n- **Problem:** Remove worktree when might need it (Option 2, 3)\n- **Fix:** Only cleanup for Options 1 and 4\n\n**No confirmation for discard**\n- **Problem:** Accidentally delete work\n- **Fix:** Require typed \"discard\" confirmation\n\n## Red Flags\n\n**Never:**\n- Proceed with failing tests\n- Merge without verifying tests on result\n- Delete work without confirmation\n- Force-push without explicit request\n\n**Always:**\n- Verify tests before offering options\n- Present exactly 4 options\n- Get typed confirmation for Option 4\n- Clean up worktree for Options 1 & 4 only\n\n## Integration\n\n**Called by:**\n- **subagent-driven-development** (Step 7) - After all tasks complete\n- **executing-plans** (Step 5) - After all batches complete\n\n**Pairs with:**\n- **using-git-worktrees** - Cleans up worktree created by that skill', 1, 1, 0, '吴同', 2, '2026-06-24 17:19:44', '吴同', NULL, '2026-06-24 17:19:44', NULL);
INSERT INTO `kb_skills` VALUES (7, 1001, 'prototype-text', '将功能级 PRD 转换为逐页面的文字版原型。使用 @docs/features/FEAT-xxx/02-prd.md 或等价 PRD 文件，以及 .cursor/commands/03-prototype-text.md，按页面拆分结构、字段、交互、状态与可测试点。遇到布局、交互、状态等不明确时，必须通过 AskQuestion 弹窗一问一答澄清，哪怕功能看起来很简单。', '/skills/prototype-text', '# /prototype-text Skill（通用）\n\n## 概览\n\n本 Skill 用于在**已有 PRD** 的基础上，生成“文字版原型”（不画图、不写代码），与项目命令 `.cursor/commands/03-prototype-text.md` 配套使用。\n\n目标：**把任何功能级 PRD，细化到“前端/后端可以直接按字段和交互实现”的粒度**。\n\n关键要求：\n\n- 是通用的：适用于任意功能模块，而不是某个具体业务。\n- 像 `/feature-clarify` 一样：**不确定就问**，通过弹窗选项与用户多轮一问一答澄清细节。\n\n## 适用时机（When to Use）\n\n在以下情况，必须使用本 Skill：\n\n- 用户执行 `/prototype-text` 或 `/03-prototype-text`，且：\n  - 已引用某个功能的 PRD 文件，例如：\n    - `@docs/features/FEAT-xxx/02-prd.md`\n    - 或者其他项目约定的 PRD 路径；\n  - 命令内容来自 `.cursor/commands/03-prototype-text.md` 或等价规范。\n- 目的：生成/更新 `docs/features/FEAT-xxx/03-prototype-text.md`（或同类路径）的文字版原型。\n\n不适用场景：\n\n- 用户只是讨论需求或写 PRD（应该用 `/feature-clarify` 或 `/prd-generate`）。\n- 用户在做技术方案/实现设计（应该用 `/tech-design`）。\n\n## 必要输入\n\n- **PRD 文档**：例如 `docs/features/FEAT-xxx/02-prd.md`  \n  - 含：背景、目标、用户与场景、功能需求列表、数据与权限、交互与异常、依赖与风险、发布策略、任务拆解等。\n- **命令定义**：`.cursor/commands/03-prototype-text.md`  \n  - 规定输出结构：逐页面的名称/入口/字段/交互/状态/列表规则/验收点 + Gate 规则。\n- **用户的补充说明**（可选）：\n  - 例如“左侧为树形结构、右侧为列表”，“已有实现可参考”等。\n\n若缺少 PRD 引用，必须先提醒用户补充 PRD 文件引用，不要凭空造原型。\n\n## 高层流程\n\n1. **读取 PRD 与命令**\n   - 读取 PRD 文件（如 `02-prd.md`），理解：\n     - 关键用户故事与场景；\n     - 功能需求列表（FR-XX）；\n     - 数据结构与权限矩阵；\n     - 交互与异常章节。\n   - 读取 `.cursor/commands/03-prototype-text.md` 确认输出结构与 Gate 规则。\n\n2. **识别页面集合**\n   - 根据 PRD，将功能自然拆成若干页面（示例）：\n     - 列表/概览页；\n     - 新增/编辑表单页或弹窗；\n     - 详情页；\n     - 子模块专用页（如审计记录页、配置向导页等）。\n   - 页面命名应源自 PRD（不要胡编），并允许后续和用户确认/重命名。\n\n3. **交互式澄清“不确定的设计点”**\n   - 对所有**不确定**的内容，优先用 AskQuestion 工具一问一答澄清，例如：\n     - 布局：是否是“左树右表”、“上下分栏”、“向导步骤条”等；\n     - 表单呈现：弹窗 vs 新页面；\n     - 默认排序字段与顺序；\n     - 分页默认条数与可选值；\n     - 是否支持批量操作/批量失败提示形式；\n     - 二次确认弹窗文案强度等。\n   - 设计问题时，遵守：\n     - 一批 3–7 个问题，避免一次问太多；\n     - 明确【单选】或【多选】；\n     - 每个问题给 2–4 个选项 + “其它：我在后续回答里说明”。\n\n4. **逐页面生成文字原型**\n   - 按命令约定，对每个页面输出：\n     - 页面名称 & 入口；\n     - 适用角色/权限；\n     - 页面结构（区块划分与布局）；\n     - 字段清单（字段名/类型/默认值/校验/是否展示/是否可编辑）；\n     - 交互（点击/输入/提交/取消/二次确认）与按钮 enable/disable 条件；\n     - 列表规则（筛选/排序/分页/批量操作）；\n     - 状态（加载/空/错/无权限/成功）；\n     - ≥8 条可测试验收点（可直接转化为测试用例）。\n\n5. **Gate 判定与输出**\n   - 在文末根据 `.cursor/commands/03-prototype-text.md` 中的 Gate 规则做自检：\n     - 每页有结构区块；\n     - 字段清单完整（类型/默认值/校验）；\n     - 状态齐（加载/空/错/无权限/成功）；\n     - 按钮 enable/disable 规则明确；\n     - 列表规则明确（筛选/排序/分页/批量约束）；\n     - 每页 ≥8 条可测试点。\n   - 写出 Gate 判定（READY_FOR_NEXT / NOT_READY）及缺失项。\n\n## 交互原则：一问一答，不怕“烦”\n\n### 原则 1：布局/交互不确定，必须问\n\n- **不要**因为“这个功能看起来很简单”就跳过澄清。\n- 对于以下问题，除非 PRD 已经写死，否则要主动提问：\n  - 列表默认排序规则（按时间？按名称？按优先级？）；\n  - 列表分页配置（默认 10 / 20 / 50？最大多少？）；\n  - 表单是否用 Drawer、Dialog、独立页面；\n  - 是否需要批量操作，以及批量失败时的反馈形式；\n  - 是否需要固定表头、固定某些列等。\n\n### 原则 2：按钮状态必须精确\n\n- 对每一个按钮，至少要写清：\n  - **enabled** 条件；\n  - **disabled** 条件；\n  - 异步操作时（加载中）是否进入 loading 状态并禁用重复点击。\n- 特别注意：\n  - “保存”按钮：必填项/校验通过前是否可点？\n  - “提交/发布”按钮：是否依赖前置步骤完成？\n  - “删除/危险操作”按钮：是否强制二次确认？\n\n### 原则 3：列表规则要细致\n\n- 对所有列表（主列表、详情内子列表），需明确：\n  - 支持哪些筛选条件，是否多条件组合；\n  - 默认排序字段与方向；\n  - 是否允许切换排序字段；\n  - 分页默认大小、可选页大小、最大上限；\n  - 是否支持多选行，以及批量操作的约束和反馈（全部成功 / 部分失败 / 全部失败）。\n\n### 原则 4：五态齐全\n\n- 每个页面都要覆盖这五类状态：\n  - **加载态**：数据加载中；\n  - **空态**：无数据/筛选无结果；\n  - **错误态**：接口失败/网络错误；\n  - **无权限态**：用户权限不足；\n  - **成功态**：关键操作完成后的反馈（toast/提示条等）。\n\n## 输出结构推荐模板\n\n在 `docs/features/FEAT-xxx/03-prototype-text.md` 中，可按下述结构组织（示意）：\n\n## 页面 P1：XXX 列表页（如：任务列表、订单列表）\n\n### 1. 页面名称 & 入口\n### 2. 适用角色/权限\n### 3. 页面结构（区块划分）\n### 4. 字段清单\n### 5. 交互与按钮 enable/disable 规则\n### 6. 列表规则（如有）\n### 7. 状态（加载/空/错/无权限/成功）\n### 8. 可测试验收点（≥8 条）\n\n## 页面 P2：XXX 新增/编辑页\n\n...\n\n## 页面 P3：XXX 详情页\n\n...\n\n## Gate 判定\n- 产物清单：\n- 验收清单对照：\n- Gate 结论：READY_FOR_NEXT / NOT_READY\n- 缺失项（如有）：', 1, 1, 0, '吴同', 2, '2026-06-24 17:19:44', '吴同', NULL, '2026-06-24 17:19:44', NULL);
INSERT INTO `kb_skills` VALUES (8, 1001, 'receiving-code-review', 'Use when receiving code review feedback, before implementing suggestions, especially if feedback seems unclear or technically questionable - requires technical rigor and verification, not performative agreement or blind implementation', '/skills/receiving-code-review', '# Code Review Reception\n\n## Overview\n\nCode review requires technical evaluation, not emotional performance.\n\n**Core principle:** Verify before implementing. Ask before assuming. Technical correctness over social comfort.\n\n## The Response Pattern\n\n```\nWHEN receiving code review feedback:\n\n1. READ: Complete feedback without reacting\n2. UNDERSTAND: Restate requirement in own words (or ask)\n3. VERIFY: Check against codebase reality\n4. EVALUATE: Technically sound for THIS codebase?\n5. RESPOND: Technical acknowledgment or reasoned pushback\n6. IMPLEMENT: One item at a time, test each\n```\n\n## Forbidden Responses\n\n**NEVER:**\n- \"You\'re absolutely right!\" (explicit CLAUDE.md violation)\n- \"Great point!\" / \"Excellent feedback!\" (performative)\n- \"Let me implement that now\" (before verification)\n\n**INSTEAD:**\n- Restate the technical requirement\n- Ask clarifying questions\n- Push back with technical reasoning if wrong\n- Just start working (actions > words)\n\n## Handling Unclear Feedback\n\n```\nIF any item is unclear:\n  STOP - do not implement anything yet\n  ASK for clarification on unclear items\n\nWHY: Items may be related. Partial understanding = wrong implementation.\n```\n\n**Example:**\n```\nyour human partner: \"Fix 1-6\"\nYou understand 1,2,3,6. Unclear on 4,5.\n\n❌ WRONG: Implement 1,2,3,6 now, ask about 4,5 later\n✅ RIGHT: \"I understand items 1,2,3,6. Need clarification on 4 and 5 before proceeding.\"\n```\n\n## Source-Specific Handling\n\n### From your human partner\n- **Trusted** - implement after understanding\n- **Still ask** if scope unclear\n- **No performative agreement**\n- **Skip to action** or technical acknowledgment\n\n### From External Reviewers\n```\nBEFORE implementing:\n  1. Check: Technically correct for THIS codebase?\n  2. Check: Breaks existing functionality?\n  3. Check: Reason for current implementation?\n  4. Check: Works on all platforms/versions?\n  5. Check: Does reviewer understand full context?\n\nIF suggestion seems wrong:\n  Push back with technical reasoning\n\nIF can\'t easily verify:\n  Say so: \"I can\'t verify this without [X]. Should I [investigate/ask/proceed]?\"\n\nIF conflicts with your human partner\'s prior decisions:\n  Stop and discuss with your human partner first\n```\n\n**your human partner\'s rule:** \"External feedback - be skeptical, but check carefully\"\n\n## YAGNI Check for \"Professional\" Features\n\n```\nIF reviewer suggests \"implementing properly\":\n  grep codebase for actual usage\n\n  IF unused: \"This endpoint isn\'t called. Remove it (YAGNI)?\"\n  IF used: Then implement properly\n```\n\n**your human partner\'s rule:** \"You and reviewer both report to me. If we don\'t need this feature, don\'t add it.\"\n\n## Implementation Order\n\n```\nFOR multi-item feedback:\n  1. Clarify anything unclear FIRST\n  2. Then implement in this order:\n     - Blocking issues (breaks, security)\n     - Simple fixes (typos, imports)\n     - Complex fixes (refactoring, logic)\n  3. Test each fix individually\n  4. Verify no regressions\n```\n\n## When To Push Back\n\nPush back when:\n- Suggestion breaks existing functionality\n- Reviewer lacks full context\n- Violates YAGNI (unused feature)\n- Technically incorrect for this stack\n- Legacy/compatibility reasons exist\n- Conflicts with your human partner\'s architectural decisions\n\n**How to push back:**\n- Use technical reasoning, not defensiveness\n- Ask specific questions\n- Reference working tests/code\n- Involve your human partner if architectural\n\n**Signal if uncomfortable pushing back out loud:** \"Strange things are afoot at the Circle K\"\n\n## Acknowledging Correct Feedback\n\nWhen feedback IS correct:\n```\n✅ \"Fixed. [Brief description of what changed]\"\n✅ \"Good catch - [specific issue]. Fixed in [location].\"\n✅ [Just fix it and show in the code]\n\n❌ \"You\'re absolutely right!\"\n❌ \"Great point!\"\n❌ \"Thanks for catching that!\"\n❌ \"Thanks for [anything]\"\n❌ ANY gratitude expression\n```\n\n**Why no thanks:** Actions speak. Just fix it. The code itself shows you heard the feedback.\n\n**If you catch yourself about to write \"Thanks\":** DELETE IT. State the fix instead.\n\n## Gracefully Correcting Your Pushback\n\nIf you pushed back and were wrong:\n```\n✅ \"You were right - I checked [X] and it does [Y]. Implementing now.\"\n✅ \"Verified this and you\'re correct. My initial understanding was wrong because [reason]. Fixing.\"\n\n❌ Long apology\n❌ Defending why you pushed back\n❌ Over-explaining\n```\n\nState the correction factually and move on.\n\n## Common Mistakes\n\n| Mistake | Fix |\n|---------|-----|\n| Performative agreement | State requirement or just act |\n| Blind implementation | Verify against codebase first |\n| Batch without testing | One at a time, test each |\n| Assuming reviewer is right | Check if breaks things |\n| Avoiding pushback | Technical correctness > comfort |\n| Partial implementation | Clarify all items first |\n| Can\'t verify, proceed anyway | State limitation, ask for direction |\n\n## Real Examples\n\n**Performative Agreement (Bad):**\n```\nReviewer: \"Remove legacy code\"\n❌ \"You\'re absolutely right! Let me remove that...\"\n```\n\n**Technical Verification (Good):**\n```\nReviewer: \"Remove legacy code\"\n✅ \"Checking... build target is 10.15+, this API needs 13+. Need legacy for backward compat. Current impl has wrong bundle ID - fix it or drop pre-13 support?\"\n```\n\n**YAGNI (Good):**\n```\nReviewer: \"Implement proper metrics tracking with database, date filters, CSV export\"\n✅ \"Grepped codebase - nothing calls this endpoint. Remove it (YAGNI)? Or is there usage I\'m missing?\"\n```\n\n**Unclear Item (Good):**\n```\nyour human partner: \"Fix items 1-6\"\nYou understand 1,2,3,6. Unclear on 4,5.\n✅ \"Understand 1,2,3,6. Need clarification on 4 and 5 before implementing.\"\n```\n\n## GitHub Thread Replies\n\nWhen replying to inline review comments on GitHub, reply in the comment thread (`gh api repos/{owner}/{repo}/pulls/{pr}/comments/{id}/replies`), not as a top-level PR comment.\n\n## The Bottom Line\n\n**External feedback = suggestions to evaluate, not orders to follow.**\n\nVerify. Question. Then implement.\n\nNo performative agreement. Technical rigor always.', 1, 1, 0, '吴同', 2, '2026-06-24 17:19:44', '吴同', NULL, '2026-06-24 17:19:44', NULL);
INSERT INTO `kb_skills` VALUES (11, 1001, 'systematic-debugging', 'Use when encountering any bug, test failure, or unexpected behavior, before proposing fixes', '/skills/systematic-debugging', '# Systematic Debugging\n\n## Overview\n\nRandom fixes waste time and create new bugs. Quick patches mask underlying issues.\n\n**Core principle:** ALWAYS find root cause before attempting fixes. Symptom fixes are failure.\n\n**Violating the letter of this process is violating the spirit of debugging.**\n\n## The Iron Law\n\n```\nNO FIXES WITHOUT ROOT CAUSE INVESTIGATION FIRST\n```\n\nIf you haven\'t completed Phase 1, you cannot propose fixes.\n\n## When to Use\n\nUse for ANY technical issue:\n- Test failures\n- Bugs in production\n- Unexpected behavior\n- Performance problems\n- Build failures\n- Integration issues\n\n**Use this ESPECIALLY when:**\n- Under time pressure (emergencies make guessing tempting)\n- \"Just one quick fix\" seems obvious\n- You\'ve already tried multiple fixes\n- Previous fix didn\'t work\n- You don\'t fully understand the issue\n\n**Don\'t skip when:**\n- Issue seems simple (simple bugs have root causes too)\n- You\'re in a hurry (rushing guarantees rework)\n- Manager wants it fixed NOW (systematic is faster than thrashing)\n\n## The Four Phases\n\nYou MUST complete each phase before proceeding to the next.\n\n### Phase 1: Root Cause Investigation\n\n**BEFORE attempting ANY fix:**\n\n1. **Read Error Messages Carefully**\n   - Don\'t skip past errors or warnings\n   - They often contain the exact solution\n   - Read stack traces completely\n   - Note line numbers, file paths, error codes\n\n2. **Reproduce Consistently**\n   - Can you trigger it reliably?\n   - What are the exact steps?\n   - Does it happen every time?\n   - If not reproducible → gather more data, don\'t guess\n\n3. **Check Recent Changes**\n   - What changed that could cause this?\n   - Git diff, recent commits\n   - New dependencies, config changes\n   - Environmental differences\n\n4. **Gather Evidence in Multi-Component Systems**\n\n   **WHEN system has multiple components (CI → build → signing, API → service → database):**\n\n   **BEFORE proposing fixes, add diagnostic instrumentation:**\n   ```\n   For EACH component boundary:\n     - Log what data enters component\n     - Log what data exits component\n     - Verify environment/config propagation\n     - Check state at each layer\n\n   Run once to gather evidence showing WHERE it breaks\n   THEN analyze evidence to identify failing component\n   THEN investigate that specific component\n   ```\n\n   **Example (multi-layer system):**\n   ```bash\n   # Layer 1: Workflow\n   echo \"=== Secrets available in workflow: ===\"\n   echo \"IDENTITY: ${IDENTITY:+SET}${IDENTITY:-UNSET}\"\n\n   # Layer 2: Build script\n   echo \"=== Env vars in build script: ===\"\n   env | grep IDENTITY || echo \"IDENTITY not in environment\"\n\n   # Layer 3: Signing script\n   echo \"=== Keychain state: ===\"\n   security list-keychains\n   security find-identity -v\n\n   # Layer 4: Actual signing\n   codesign --sign \"$IDENTITY\" --verbose=4 \"$APP\"\n   ```\n\n   **This reveals:** Which layer fails (secrets → workflow ✓, workflow → build ✗)\n\n5. **Trace Data Flow**\n\n   **WHEN error is deep in call stack:**\n\n   See `root-cause-tracing.md` in this directory for the complete backward tracing technique.\n\n   **Quick version:**\n   - Where does bad value originate?\n   - What called this with bad value?\n   - Keep tracing up until you find the source\n   - Fix at source, not at symptom\n\n### Phase 2: Pattern Analysis\n\n**Find the pattern before fixing:**\n\n1. **Find Working Examples**\n   - Locate similar working code in same codebase\n   - What works that\'s similar to what\'s broken?\n\n2. **Compare Against References**\n   - If implementing pattern, read reference implementation COMPLETELY\n   - Don\'t skim - read every line\n   - Understand the pattern fully before applying\n\n3. **Identify Differences**\n   - What\'s different between working and broken?\n   - List every difference, however small\n   - Don\'t assume \"that can\'t matter\"\n\n4. **Understand Dependencies**\n   - What other components does this need?\n   - What settings, config, environment?\n   - What assumptions does it make?\n\n### Phase 3: Hypothesis and Testing\n\n**Scientific method:**\n\n1. **Form Single Hypothesis**\n   - State clearly: \"I think X is the root cause because Y\"\n   - Write it down\n   - Be specific, not vague\n\n2. **Test Minimally**\n   - Make the SMALLEST possible change to test hypothesis\n   - One variable at a time\n   - Don\'t fix multiple things at once\n\n3. **Verify Before Continuing**\n   - Did it work? Yes → Phase 4\n   - Didn\'t work? Form NEW hypothesis\n   - DON\'T add more fixes on top\n\n4. **When You Don\'t Know**\n   - Say \"I don\'t understand X\"\n   - Don\'t pretend to know\n   - Ask for help\n   - Research more\n\n### Phase 4: Implementation\n\n**Fix the root cause, not the symptom:**\n\n1. **Create Failing Test Case**\n   - Simplest possible reproduction\n   - Automated test if possible\n   - One-off test script if no framework\n   - MUST have before fixing\n   - Use the `superpowers:test-driven-development` skill for writing proper failing tests\n\n2. **Implement Single Fix**\n   - Address the root cause identified\n   - ONE change at a time\n   - No \"while I\'m here\" improvements\n   - No bundled refactoring\n\n3. **Verify Fix**\n   - Test passes now?\n   - No other tests broken?\n   - Issue actually resolved?\n\n4. **If Fix Doesn\'t Work**\n   - STOP\n   - Count: How many fixes have you tried?\n   - If < 3: Return to Phase 1, re-analyze with new information\n   - **If ≥ 3: STOP and question the architecture (step 5 below)**\n   - DON\'T attempt Fix #4 without architectural discussion\n\n5. **If 3+ Fixes Failed: Question Architecture**\n\n   **Pattern indicating architectural problem:**\n   - Each fix reveals new shared state/coupling/problem in different place\n   - Fixes require \"massive refactoring\" to implement\n   - Each fix creates new symptoms elsewhere\n\n   **STOP and question fundamentals:**\n   - Is this pattern fundamentally sound?\n   - Are we \"sticking with it through sheer inertia\"?\n   - Should we refactor architecture vs. continue fixing symptoms?\n\n   **Discuss with your human partner before attempting more fixes**\n\n   This is NOT a failed hypothesis - this is a wrong architecture.\n\n## Red Flags - STOP and Follow Process\n\nIf you catch yourself thinking:\n- \"Quick fix for now, investigate later\"\n- \"Just try changing X and see if it works\"\n- \"Add multiple changes, run tests\"\n- \"Skip the test, I\'ll manually verify\"\n- \"It\'s probably X, let me fix that\"\n- \"I don\'t fully understand but this might work\"\n- \"Pattern says X but I\'ll adapt it differently\"\n- \"Here are the main problems: [lists fixes without investigation]\"\n- Proposing solutions before tracing data flow\n- **\"One more fix attempt\" (when already tried 2+)**\n- **Each fix reveals new problem in different place**\n\n**ALL of these mean: STOP. Return to Phase 1.**\n\n**If 3+ fixes failed:** Question the architecture (see Phase 4.5)\n\n## your human partner\'s Signals You\'re Doing It Wrong\n\n**Watch for these redirections:**\n- \"Is that not happening?\" - You assumed without verifying\n- \"Will it show us...?\" - You should have added evidence gathering\n- \"Stop guessing\" - You\'re proposing fixes without understanding\n- \"Ultrathink this\" - Question fundamentals, not just symptoms\n- \"We\'re stuck?\" (frustrated) - Your approach isn\'t working\n\n**When you see these:** STOP. Return to Phase 1.\n\n## Common Rationalizations\n\n| Excuse | Reality |\n|--------|---------|\n| \"Issue is simple, don\'t need process\" | Simple issues have root causes too. Process is fast for simple bugs. |\n| \"Emergency, no time for process\" | Systematic debugging is FASTER than guess-and-check thrashing. |\n| \"Just try this first, then investigate\" | First fix sets the pattern. Do it right from the start. |\n| \"I\'ll write test after confirming fix works\" | Untested fixes don\'t stick. Test first proves it. |\n| \"Multiple fixes at once saves time\" | Can\'t isolate what worked. Causes new bugs. |\n| \"Reference too long, I\'ll adapt the pattern\" | Partial understanding guarantees bugs. Read it completely. |\n| \"I see the problem, let me fix it\" | Seeing symptoms ≠ understanding root cause. |\n| \"One more fix attempt\" (after 2+ failures) | 3+ failures = architectural problem. Question pattern, don\'t fix again. |\n\n## Quick Reference\n\n| Phase | Key Activities | Success Criteria |\n|-------|---------------|------------------|\n| **1. Root Cause** | Read errors, reproduce, check changes, gather evidence | Understand WHAT and WHY |\n| **2. Pattern** | Find working examples, compare | Identify differences |\n| **3. Hypothesis** | Form theory, test minimally | Confirmed or new hypothesis |\n| **4. Implementation** | Create test, fix, verify | Bug resolved, tests pass |\n\n## When Process Reveals \"No Root Cause\"\n\nIf systematic investigation reveals issue is truly environmental, timing-dependent, or external:\n\n1. You\'ve completed the process\n2. Document what you investigated\n3. Implement appropriate handling (retry, timeout, error message)\n4. Add monitoring/logging for future investigation\n\n**But:** 95% of \"no root cause\" cases are incomplete investigation.\n\n## Supporting Techniques\n\nThese techniques are part of systematic debugging and available in this directory:\n\n- **`root-cause-tracing.md`** - Trace bugs backward through call stack to find original trigger\n- **`defense-in-depth.md`** - Add validation at multiple layers after finding root cause\n- **`condition-based-waiting.md`** - Replace arbitrary timeouts with condition polling\n\n**Related skills:**\n- **superpowers:test-driven-development** - For creating failing test case (Phase 4, Step 1)\n- **superpowers:verification-before-completion** - Verify fix worked before claiming success\n\n## Real-World Impact\n\nFrom debugging sessions:\n- Systematic approach: 15-30 minutes to fix\n- Random fixes approach: 2-3 hours of thrashing\n- First-time fix rate: 95% vs 40%\n- New bugs introduced: Near zero vs common', 1, 1, 0, '吴同', 2, '2026-06-24 17:19:45', '吴同', NULL, '2026-06-25 21:00:52', NULL);
INSERT INTO `kb_skills` VALUES (12, 1001, 'test-driven-development', 'Use when implementing any feature or bugfix, before writing implementation code', '/skills/test-driven-development', '# Test-Driven Development (TDD)\n\n## Overview\n\nWrite the test first. Watch it fail. Write minimal code to pass.\n\n**Core principle:** If you didn\'t watch the test fail, you don\'t know if it tests the right thing.\n\n**Violating the letter of the rules is violating the spirit of the rules.**\n\n## When to Use\n\n**Always:**\n- New features\n- Bug fixes\n- Refactoring\n- Behavior changes\n\n**Exceptions (ask your human partner):**\n- Throwaway prototypes\n- Generated code\n- Configuration files\n\nThinking \"skip TDD just this once\"? Stop. That\'s rationalization.\n\n## The Iron Law\n\n```\nNO PRODUCTION CODE WITHOUT A FAILING TEST FIRST\n```\n\nWrite code before the test? Delete it. Start over.\n\n**No exceptions:**\n- Don\'t keep it as \"reference\"\n- Don\'t \"adapt\" it while writing tests\n- Don\'t look at it\n- Delete means delete\n\nImplement fresh from tests. Period.\n\n## Red-Green-Refactor\n\n```dot\ndigraph tdd_cycle {\n    rankdir=LR;\n    red [label=\"RED\\nWrite failing test\", shape=box, style=filled, fillcolor=\"#ffcccc\"];\n    verify_red [label=\"Verify fails\\ncorrectly\", shape=diamond];\n    green [label=\"GREEN\\nMinimal code\", shape=box, style=filled, fillcolor=\"#ccffcc\"];\n    verify_green [label=\"Verify passes\\nAll green\", shape=diamond];\n    refactor [label=\"REFACTOR\\nClean up\", shape=box, style=filled, fillcolor=\"#ccccff\"];\n    next [label=\"Next\", shape=ellipse];\n\n    red -> verify_red;\n    verify_red -> green [label=\"yes\"];\n    verify_red -> red [label=\"wrong\\nfailure\"];\n    green -> verify_green;\n    verify_green -> refactor [label=\"yes\"];\n    verify_green -> green [label=\"no\"];\n    refactor -> verify_green [label=\"stay\\ngreen\"];\n    verify_green -> next;\n    next -> red;\n}\n```\n\n### RED - Write Failing Test\n\nWrite one minimal test showing what should happen.\n\n<Good>\n```typescript\ntest(\'retries failed operations 3 times\', async () => {\n  let attempts = 0;\n  const operation = () => {\n    attempts++;\n    if (attempts < 3) throw new Error(\'fail\');\n    return \'success\';\n  };\n\n  const result = await retryOperation(operation);\n\n  expect(result).toBe(\'success\');\n  expect(attempts).toBe(3);\n});\n```\nClear name, tests real behavior, one thing\n</Good>\n\n<Bad>\n```typescript\ntest(\'retry works\', async () => {\n  const mock = jest.fn()\n    .mockRejectedValueOnce(new Error())\n    .mockRejectedValueOnce(new Error())\n    .mockResolvedValueOnce(\'success\');\n  await retryOperation(mock);\n  expect(mock).toHaveBeenCalledTimes(3);\n});\n```\nVague name, tests mock not code\n</Bad>\n\n**Requirements:**\n- One behavior\n- Clear name\n- Real code (no mocks unless unavoidable)\n\n### Verify RED - Watch It Fail\n\n**MANDATORY. Never skip.**\n\n```bash\nnpm test path/to/test.test.ts\n```\n\nConfirm:\n- Test fails (not errors)\n- Failure message is expected\n- Fails because feature missing (not typos)\n\n**Test passes?** You\'re testing existing behavior. Fix test.\n\n**Test errors?** Fix error, re-run until it fails correctly.\n\n### GREEN - Minimal Code\n\nWrite simplest code to pass the test.\n\n<Good>\n```typescript\nasync function retryOperation<T>(fn: () => Promise<T>): Promise<T> {\n  for (let i = 0; i < 3; i++) {\n    try {\n      return await fn();\n    } catch (e) {\n      if (i === 2) throw e;\n    }\n  }\n  throw new Error(\'unreachable\');\n}\n```\nJust enough to pass\n</Good>\n\n<Bad>\n```typescript\nasync function retryOperation<T>(\n  fn: () => Promise<T>,\n  options?: {\n    maxRetries?: number;\n    backoff?: \'linear\' | \'exponential\';\n    onRetry?: (attempt: number) => void;\n  }\n): Promise<T> {\n  // YAGNI\n}\n```\nOver-engineered\n</Bad>\n\nDon\'t add features, refactor other code, or \"improve\" beyond the test.\n\n### Verify GREEN - Watch It Pass\n\n**MANDATORY.**\n\n```bash\nnpm test path/to/test.test.ts\n```\n\nConfirm:\n- Test passes\n- Other tests still pass\n- Output pristine (no errors, warnings)\n\n**Test fails?** Fix code, not test.\n\n**Other tests fail?** Fix now.\n\n### REFACTOR - Clean Up\n\nAfter green only:\n- Remove duplication\n- Improve names\n- Extract helpers\n\nKeep tests green. Don\'t add behavior.\n\n### Repeat\n\nNext failing test for next feature.\n\n## Good Tests\n\n| Quality | Good | Bad |\n|---------|------|-----|\n| **Minimal** | One thing. \"and\" in name? Split it. | `test(\'validates email and domain and whitespace\')` |\n| **Clear** | Name describes behavior | `test(\'test1\')` |\n| **Shows intent** | Demonstrates desired API | Obscures what code should do |\n\n## Why Order Matters\n\n**\"I\'ll write tests after to verify it works\"**\n\nTests written after code pass immediately. Passing immediately proves nothing:\n- Might test wrong thing\n- Might test implementation, not behavior\n- Might miss edge cases you forgot\n- You never saw it catch the bug\n\nTest-first forces you to see the test fail, proving it actually tests something.\n\n**\"I already manually tested all the edge cases\"**\n\nManual testing is ad-hoc. You think you tested everything but:\n- No record of what you tested\n- Can\'t re-run when code changes\n- Easy to forget cases under pressure\n- \"It worked when I tried it\" ≠ comprehensive\n\nAutomated tests are systematic. They run the same way every time.\n\n**\"Deleting X hours of work is wasteful\"**\n\nSunk cost fallacy. The time is already gone. Your choice now:\n- Delete and rewrite with TDD (X more hours, high confidence)\n- Keep it and add tests after (30 min, low confidence, likely bugs)\n\nThe \"waste\" is keeping code you can\'t trust. Working code without real tests is technical debt.\n\n**\"TDD is dogmatic, being pragmatic means adapting\"**\n\nTDD IS pragmatic:\n- Finds bugs before commit (faster than debugging after)\n- Prevents regressions (tests catch breaks immediately)\n- Documents behavior (tests show how to use code)\n- Enables refactoring (change freely, tests catch breaks)\n\n\"Pragmatic\" shortcuts = debugging in production = slower.\n\n**\"Tests after achieve the same goals - it\'s spirit not ritual\"**\n\nNo. Tests-after answer \"What does this do?\" Tests-first answer \"What should this do?\"\n\nTests-after are biased by your implementation. You test what you built, not what\'s required. You verify remembered edge cases, not discovered ones.\n\nTests-first force edge case discovery before implementing. Tests-after verify you remembered everything (you didn\'t).\n\n30 minutes of tests after ≠ TDD. You get coverage, lose proof tests work.\n\n## Common Rationalizations\n\n| Excuse | Reality |\n|--------|---------|\n| \"Too simple to test\" | Simple code breaks. Test takes 30 seconds. |\n| \"I\'ll test after\" | Tests passing immediately prove nothing. |\n| \"Tests after achieve same goals\" | Tests-after = \"what does this do?\" Tests-first = \"what should this do?\" |\n| \"Already manually tested\" | Ad-hoc ≠ systematic. No record, can\'t re-run. |\n| \"Deleting X hours is wasteful\" | Sunk cost fallacy. Keeping unverified code is technical debt. |\n| \"Keep as reference, write tests first\" | You\'ll adapt it. That\'s testing after. Delete means delete. |\n| \"Need to explore first\" | Fine. Throw away exploration, start with TDD. |\n| \"Test hard = design unclear\" | Listen to test. Hard to test = hard to use. |\n| \"TDD will slow me down\" | TDD faster than debugging. Pragmatic = test-first. |\n| \"Manual test faster\" | Manual doesn\'t prove edge cases. You\'ll re-test every change. |\n| \"Existing code has no tests\" | You\'re improving it. Add tests for existing code. |\n\n## Red Flags - STOP and Start Over\n\n- Code before test\n- Test after implementation\n- Test passes immediately\n- Can\'t explain why test failed\n- Tests added \"later\"\n- Rationalizing \"just this once\"\n- \"I already manually tested it\"\n- \"Tests after achieve the same purpose\"\n- \"It\'s about spirit not ritual\"\n- \"Keep as reference\" or \"adapt existing code\"\n- \"Already spent X hours, deleting is wasteful\"\n- \"TDD is dogmatic, I\'m being pragmatic\"\n- \"This is different because...\"\n\n**All of these mean: Delete code. Start over with TDD.**\n\n## Example: Bug Fix\n\n**Bug:** Empty email accepted\n\n**RED**\n```typescript\ntest(\'rejects empty email\', async () => {\n  const result = await submitForm({ email: \'\' });\n  expect(result.error).toBe(\'Email required\');\n});\n```\n\n**Verify RED**\n```bash\n$ npm test\nFAIL: expected \'Email required\', got undefined\n```\n\n**GREEN**\n```typescript\nfunction submitForm(data: FormData) {\n  if (!data.email?.trim()) {\n    return { error: \'Email required\' };\n  }\n  // ...\n}\n```\n\n**Verify GREEN**\n```bash\n$ npm test\nPASS\n```\n\n**REFACTOR**\nExtract validation for multiple fields if needed.\n\n## Verification Checklist\n\nBefore marking work complete:\n\n- [ ] Every new function/method has a test\n- [ ] Watched each test fail before implementing\n- [ ] Each test failed for expected reason (feature missing, not typo)\n- [ ] Wrote minimal code to pass each test\n- [ ] All tests pass\n- [ ] Output pristine (no errors, warnings)\n- [ ] Tests use real code (mocks only if unavoidable)\n- [ ] Edge cases and errors covered\n\nCan\'t check all boxes? You skipped TDD. Start over.\n\n## When Stuck\n\n| Problem | Solution |\n|---------|----------|\n| Don\'t know how to test | Write wished-for API. Write assertion first. Ask your human partner. |\n| Test too complicated | Design too complicated. Simplify interface. |\n| Must mock everything | Code too coupled. Use dependency injection. |\n| Test setup huge | Extract helpers. Still complex? Simplify design. |\n\n## Debugging Integration\n\nBug found? Write failing test reproducing it. Follow TDD cycle. Test proves fix and prevents regression.\n\nNever fix bugs without a test.\n\n## Testing Anti-Patterns\n\nWhen adding mocks or test utilities, read @testing-anti-patterns.md to avoid common pitfalls:\n- Testing mock behavior instead of real behavior\n- Adding test-only methods to production classes\n- Mocking without understanding dependencies\n\n## Final Rule\n\n```\nProduction code → test exists and failed first\nOtherwise → not TDD\n```\n\nNo exceptions without your human partner\'s permission.', 1, 1, 0, '吴同', 2, '2026-06-24 17:19:45', '超级管理员', NULL, '2026-06-25 22:07:24', NULL);
INSERT INTO `kb_skills` VALUES (13, 1001, 'using-git-worktrees', 'Creates isolated git worktrees for feature work with smart path selection and safety checks.', '/skills/using-git-worktrees', '# Using Git Worktrees\n\n## Overview\n\nGit worktrees create isolated workspaces sharing the same repository, allowing work on multiple branches simultaneously without switching.\n\n**Core principle:** Systematic directory selection + safety verification = reliable isolation.\n\n**Announce at start:** \"I\'m using the using-git-worktrees skill to set up an isolated workspace.\"\n\n## Directory Selection Process\n\nFollow this priority order:\n\n### 1. Check Existing Directories\n\n```bash\n# Check in priority order\nls -d .worktrees 2>/dev/null     # Preferred (hidden)\nls -d worktrees 2>/dev/null      # Alternative\n```\n\n**If found:** Use that directory. If both exist, `.worktrees` wins.\n\n### 2. Check CLAUDE.md\n\n```bash\ngrep -i \"worktree.*director\" CLAUDE.md 2>/dev/null\n```\n\n**If preference specified:** Use it without asking.\n\n### 3. Ask User\n\nIf no directory exists and no CLAUDE.md preference:\n\n```\nNo worktree directory found. Where should I create worktrees?\n\n1. .worktrees/ (project-local, hidden)\n2. ~/.config/superpowers/worktrees/<project-name>/ (global location)\n\nWhich would you prefer?\n```\n\n## Safety Verification\n\n### For Project-Local Directories (.worktrees or worktrees)\n\n**MUST verify directory is ignored before creating worktree:**\n\n```bash\n# Check if directory is ignored (respects local, global, and system gitignore)\ngit check-ignore -q .worktrees 2>/dev/null || git check-ignore -q worktrees 2>/dev/null\n```\n\n**If NOT ignored:**\n\nPer Jesse\'s rule \"Fix broken things immediately\":\n1. Add appropriate line to .gitignore\n2. Commit the change\n3. Proceed with worktree creation\n\n**Why critical:** Prevents accidentally committing worktree contents to repository.\n\n### For Global Directory (~/.config/superpowers/worktrees)\n\nNo .gitignore verification needed - outside project entirely.\n\n## Creation Steps\n\n### 1. Detect Project Name\n\n```bash\nproject=$(basename \"$(git rev-parse --show-toplevel)\")\n```\n\n### 2. Create Worktree\n\n```bash\n# Determine full path\ncase $LOCATION in\n  .worktrees|worktrees)\n    path=\"$LOCATION/$BRANCH_NAME\"\n    ;;\n  ~/.config/superpowers/worktrees/*)\n    path=\"~/.config/superpowers/worktrees/$project/$BRANCH_NAME\"\n    ;;\nesac\n\n# Create worktree with new branch\ngit worktree add \"$path\" -b \"$BRANCH_NAME\"\ncd \"$path\"\n```\n\n### 3. Run Project Setup\n\nAuto-detect and run appropriate setup:\n\n```bash\n# Node.js\nif [ -f package.json ]; then npm install; fi\n\n# Rust\nif [ -f Cargo.toml ]; then cargo build; fi\n\n# Python\nif [ -f requirements.txt ]; then pip install -r requirements.txt; fi\nif [ -f pyproject.toml ]; then poetry install; fi\n\n# Go\nif [ -f go.mod ]; then go mod download; fi\n```\n\n### 4. Verify Clean Baseline\n\nRun tests to ensure worktree starts clean:\n\n```bash\n# Examples - use project-appropriate command\nnpm test\ncargo test\npytest\ngo test ./...\n```\n\n**If tests fail:** Report failures, ask whether to proceed or investigate.\n\n**If tests pass:** Report ready.\n\n### 5. Report Location\n\n```\nWorktree ready at <full-path>\nTests passing (<N> tests, 0 failures)\nReady to implement <feature-name>\n```\n\n## Quick Reference\n\n| Situation | Action |\n|-----------|--------|\n| `.worktrees/` exists | Use it (verify ignored) |\n| `worktrees/` exists | Use it (verify ignored) |\n| Both exist | Use `.worktrees/` |\n| Neither exists | Check CLAUDE.md → Ask user |\n| Directory not ignored | Add to .gitignore + commit |\n| Tests fail during baseline | Report failures + ask |\n| No package.json/Cargo.toml | Skip dependency install |\n\n## Common Mistakes\n\n### Skipping ignore verification\n\n- **Problem:** Worktree contents get tracked, pollute git status\n- **Fix:** Always use `git check-ignore` before creating project-local worktree\n\n### Assuming directory location\n\n- **Problem:** Creates inconsistency, violates project conventions\n- **Fix:** Follow priority: existing > CLAUDE.md > ask\n\n### Proceeding with failing tests\n\n- **Problem:** Can\'t distinguish new bugs from pre-existing issues\n- **Fix:** Report failures, get explicit permission to proceed\n\n### Hardcoding setup commands\n\n- **Problem:** Breaks on projects using different tools\n- **Fix:** Auto-detect from project files (package.json, etc.)\n\n## Example Workflow\n\n```\nYou: I\'m using the using-git-worktrees skill to set up an isolated workspace.\n\n[Check .worktrees/ - exists]\n[Verify ignored - git check-ignore confirms .worktrees/ is ignored]\n[Create worktree: git worktree add .worktrees/auth -b feature/auth]\n[Run npm install]\n[Run npm test - 47 passing]\n\nWorktree ready at /Users/jesse/myproject/.worktrees/auth\nTests passing (47 tests, 0 failures)\nReady to implement auth feature\n```\n\n## Red Flags\n\n**Never:**\n- Create worktree without verifying it\'s ignored (project-local)\n- Skip baseline test verification\n- Proceed with failing tests without asking\n- Assume directory location when ambiguous\n- Skip CLAUDE.md check\n\n**Always:**\n- Follow directory priority: existing > CLAUDE.md > ask\n- Verify directory is ignored for project-local\n- Auto-detect and run project setup\n- Verify clean test baseline\n\n## Integration\n\n**Called by:**\n- **brainstorming** (Phase 4) - REQUIRED when design is approved and implementation follows\n- **subagent-driven-development** - REQUIRED before executing any tasks\n- **executing-plans** - REQUIRED before executing any tasks\n- Any skill needing isolated workspace\n\n**Pairs with:**\n- **finishing-a-development-branch** - REQUIRED for cleanup after work complete', 1, 1, 0, '吴同', 2, '2026-06-24 17:19:45', '吴同', NULL, '2026-06-26 13:37:58', NULL);
INSERT INTO `kb_skills` VALUES (14, 1001, 'using-superpowers', 'Use when starting any conversation - establishes how to find and use skills, requiring Skill tool invocation before ANY response including clarifying questions', '/skills/using-superpowers', '<SUBAGENT-STOP>\nIf you were dispatched as a subagent to execute a specific task, skip this skill.\n</SUBAGENT-STOP>\n\n<EXTREMELY-IMPORTANT>\nIf you think there is even a 1% chance a skill might apply to what you are doing, you ABSOLUTELY MUST invoke the skill.\n\nIF A SKILL APPLIES TO YOUR TASK, YOU DO NOT HAVE A CHOICE. YOU MUST USE IT.\n\nThis is not negotiable. This is not optional. You cannot rationalize your way out of this.\n</EXTREMELY-IMPORTANT>\n\n## Instruction Priority\n\nSuperpowers skills override default system prompt behavior, but **user instructions always take precedence**:\n\n1. **User\'s explicit instructions** (CLAUDE.md, GEMINI.md, AGENTS.md, direct requests) — highest priority\n2. **Superpowers skills** — override default system behavior where they conflict\n3. **Default system prompt** — lowest priority\n\nIf CLAUDE.md, GEMINI.md, or AGENTS.md says \"don\'t use TDD\" and a skill says \"always use TDD,\" follow the user\'s instructions. The user is in control.\n\n## How to Access Skills\n\n**In Claude Code:** Use the `Skill` tool. When you invoke a skill, its content is loaded and presented to you—follow it directly. Never use the Read tool on skill files.\n\n**In Gemini CLI:** Skills activate via the `activate_skill` tool. Gemini loads skill metadata at session start and activates the full content on demand.\n\n**In other environments:** Check your platform\'s documentation for how skills are loaded.\n\n## Platform Adaptation\n\nSkills use Claude Code tool names. Non-CC platforms: see `references/codex-tools.md` (Codex) for tool equivalents. Gemini CLI users get the tool mapping loaded automatically via GEMINI.md.\n\n# Using Skills\n\n## The Rule\n\n**Invoke relevant or requested skills BEFORE any response or action.** Even a 1% chance a skill might apply means that you should invoke the skill to check. If an invoked skill turns out to be wrong for the situation, you don\'t need to use it.\n\n```dot\ndigraph skill_flow {\n    \"User message received\" [shape=doublecircle];\n    \"About to EnterPlanMode?\" [shape=doublecircle];\n    \"Already brainstormed?\" [shape=diamond];\n    \"Invoke brainstorming skill\" [shape=box];\n    \"Might any skill apply?\" [shape=diamond];\n    \"Invoke Skill tool\" [shape=box];\n    \"Announce: \'Using [skill] to [purpose]\'\" [shape=box];\n    \"Has checklist?\" [shape=diamond];\n    \"Create TodoWrite todo per item\" [shape=box];\n    \"Follow skill exactly\" [shape=box];\n    \"Respond (including clarifications)\" [shape=doublecircle];\n\n    \"About to EnterPlanMode?\" -> \"Already brainstormed?\";\n    \"Already brainstormed?\" -> \"Invoke brainstorming skill\" [label=\"no\"];\n    \"Already brainstormed?\" -> \"Might any skill apply?\" [label=\"yes\"];\n    \"Invoke brainstorming skill\" -> \"Might any skill apply?\";\n\n    \"User message received\" -> \"Might any skill apply?\";\n    \"Might any skill apply?\" -> \"Invoke Skill tool\" [label=\"yes, even 1%\"];\n    \"Might any skill apply?\" -> \"Respond (including clarifications)\" [label=\"definitely not\"];\n    \"Invoke Skill tool\" -> \"Announce: \'Using [skill] to [purpose]\'\";\n    \"Announce: \'Using [skill] to [purpose]\'\" -> \"Has checklist?\";\n    \"Has checklist?\" -> \"Create TodoWrite todo per item\" [label=\"yes\"];\n    \"Has checklist?\" -> \"Follow skill exactly\" [label=\"no\"];\n    \"Create TodoWrite todo per item\" -> \"Follow skill exactly\";\n}\n```\n\n## Red Flags\n\nThese thoughts mean STOP—you\'re rationalizing:\n\n| Thought | Reality |\n|---------|---------|\n| \"This is just a simple question\" | Questions are tasks. Check for skills. |\n| \"I need more context first\" | Skill check comes BEFORE clarifying questions. |\n| \"Let me explore the codebase first\" | Skills tell you HOW to explore. Check first. |\n| \"I can check git/files quickly\" | Files lack conversation context. Check for skills. |\n| \"Let me gather information first\" | Skills tell you HOW to gather information. |\n| \"This doesn\'t need a formal skill\" | If a skill exists, use it. |\n| \"I remember this skill\" | Skills evolve. Read current version. |\n| \"This doesn\'t count as a task\" | Action = task. Check for skills. |\n| \"The skill is overkill\" | Simple things become complex. Use it. |\n| \"I\'ll just do this one thing first\" | Check BEFORE doing anything. |\n| \"This feels productive\" | Undisciplined action wastes time. Skills prevent this. |\n| \"I know what that means\" | Knowing the concept ≠ using the skill. Invoke it. |\n\n## Skill Priority\n\nWhen multiple skills could apply, use this order:\n\n1. **Process skills first** (brainstorming, debugging) - these determine HOW to approach the task\n2. **Implementation skills second** (frontend-design, mcp-builder) - these guide execution\n\n\"Let\'s build X\" → brainstorming first, then implementation skills.\n\"Fix this bug\" → debugging first, then domain-specific skills.\n\n## Skill Types\n\n**Rigid** (TDD, debugging): Follow exactly. Don\'t adapt away discipline.\n\n**Flexible** (patterns): Adapt principles to context.\n\nThe skill itself tells you which.\n\n## User Instructions\n\nInstructions say WHAT, not HOW. \"Add X\" or \"Fix Y\" doesn\'t mean skip workflows.', 1, 1, 0, '吴同', 2, '2026-06-24 17:19:45', '吴同', NULL, '2026-06-24 17:19:45', NULL);
INSERT INTO `kb_skills` VALUES (15, 1001, 'verification-before-completion', 'Use when about to claim work is complete, fixed, or passing, before committing or creating PRs - requires running verification commands and confirming output before making any success claims; evidence before assertions always', '/skills/verification-before-completion', '# Verification Before Completion\n\n## Overview\n\nClaiming work is complete without verification is dishonesty, not efficiency.\n\n**Core principle:** Evidence before claims, always.\n\n**Violating the letter of this rule is violating the spirit of this rule.**\n\n## The Iron Law\n\n```\nNO COMPLETION CLAIMS WITHOUT FRESH VERIFICATION EVIDENCE\n```\n\nIf you haven\'t run the verification command in this message, you cannot claim it passes.\n\n## The Gate Function\n\n```\nBEFORE claiming any status or expressing satisfaction:\n\n1. IDENTIFY: What command proves this claim?\n2. RUN: Execute the FULL command (fresh, complete)\n3. READ: Full output, check exit code, count failures\n4. VERIFY: Does output confirm the claim?\n   - If NO: State actual status with evidence\n   - If YES: State claim WITH evidence\n5. ONLY THEN: Make the claim\n\nSkip any step = lying, not verifying\n```\n\n## Common Failures\n\n| Claim | Requires | Not Sufficient |\n|-------|----------|----------------|\n| Tests pass | Test command output: 0 failures | Previous run, \"should pass\" |\n| Linter clean | Linter output: 0 errors | Partial check, extrapolation |\n| Build succeeds | Build command: exit 0 | Linter passing, logs look good |\n| Bug fixed | Test original symptom: passes | Code changed, assumed fixed |\n| Regression test works | Red-green cycle verified | Test passes once |\n| Agent completed | VCS diff shows changes | Agent reports \"success\" |\n| Requirements met | Line-by-line checklist | Tests passing |\n\n## Red Flags - STOP\n\n- Using \"should\", \"probably\", \"seems to\"\n- Expressing satisfaction before verification (\"Great!\", \"Perfect!\", \"Done!\", etc.)\n- About to commit/push/PR without verification\n- Trusting agent success reports\n- Relying on partial verification\n- Thinking \"just this once\"\n- Tired and wanting work over\n- **ANY wording implying success without having run verification**\n\n## Rationalization Prevention\n\n| Excuse | Reality |\n|--------|---------|\n| \"Should work now\" | RUN the verification |\n| \"I\'m confident\" | Confidence ≠ evidence |\n| \"Just this once\" | No exceptions |\n| \"Linter passed\" | Linter ≠ compiler |\n| \"Agent said success\" | Verify independently |\n| \"I\'m tired\" | Exhaustion ≠ excuse |\n| \"Partial check is enough\" | Partial proves nothing |\n| \"Different words so rule doesn\'t apply\" | Spirit over letter |\n\n## Key Patterns\n\n**Tests:**\n```\n✅ [Run test command] [See: 34/34 pass] \"All tests pass\"\n❌ \"Should pass now\" / \"Looks correct\"\n```\n\n**Regression tests (TDD Red-Green):**\n```\n✅ Write → Run (pass) → Revert fix → Run (MUST FAIL) → Restore → Run (pass)\n❌ \"I\'ve written a regression test\" (without red-green verification)\n```\n\n**Build:**\n```\n✅ [Run build] [See: exit 0] \"Build passes\"\n❌ \"Linter passed\" (linter doesn\'t check compilation)\n```\n\n**Requirements:**\n```\n✅ Re-read plan → Create checklist → Verify each → Report gaps or completion\n❌ \"Tests pass, phase complete\"\n```\n\n**Agent delegation:**\n```\n✅ Agent reports success → Check VCS diff → Verify changes → Report actual state\n❌ Trust agent report\n```\n\n## Why This Matters\n\nFrom 24 failure memories:\n- your human partner said \"I don\'t believe you\" - trust broken\n- Undefined functions shipped - would crash\n- Missing requirements shipped - incomplete features\n- Time wasted on false completion → redirect → rework\n- Violates: \"Honesty is a core value. If you lie, you\'ll be replaced.\"\n\n## When To Apply\n\n**ALWAYS before:**\n- ANY variation of success/completion claims\n- ANY expression of satisfaction\n- ANY positive statement about work state\n- Committing, PR creation, task completion\n- Moving to next task\n- Delegating to agents\n\n**Rule applies to:**\n- Exact phrases\n- Paraphrases and synonyms\n- Implications of success\n- ANY communication suggesting completion/correctness\n\n## The Bottom Line\n\n**No shortcuts for verification.**\n\nRun the command. Read the output. THEN claim the result.\n\nThis is non-negotiable.', 1, 1, 0, '吴同', 2, '2026-06-24 17:19:45', '吴同', NULL, '2026-06-24 17:19:45', NULL);
INSERT INTO `kb_skills` VALUES (16, 1001, 'writing-plans', 'Use when you have a spec or requirements for a multi-step task, before touching code', '/skills/writing-plans', '# Writing Plans\n\n## Overview\n\nWrite comprehensive implementation plans assuming the engineer has zero context for our codebase and questionable taste. Document everything they need to know: which files to touch for each task, code, testing, docs they might need to check, how to test it. Give them the whole plan as bite-sized tasks. DRY. YAGNI. TDD. Frequent commits.\n\nAssume they are a skilled developer, but know almost nothing about our toolset or problem domain. Assume they don\'t know good test design very well.\n\n**Announce at start:** \"I\'m using the writing-plans skill to create the implementation plan.\"\n\n**Context:** This should be run in a dedicated worktree (created by brainstorming skill).\n\n**Save plans to:** `docs/superpowers/plans/YYYY-MM-DD-<feature-name>.md`\n- (User preferences for plan location override this default)\n\n## Scope Check\n\nIf the spec covers multiple independent subsystems, it should have been broken into sub-project specs during brainstorming. If it wasn\'t, suggest breaking this into separate plans — one per subsystem. Each plan should produce working, testable software on its own.\n\n## File Structure\n\nBefore defining tasks, map out which files will be created or modified and what each one is responsible for. This is where decomposition decisions get locked in.\n\n- Design units with clear boundaries and well-defined interfaces. Each file should have one clear responsibility.\n- You reason best about code you can hold in context at once, and your edits are more reliable when files are focused. Prefer smaller, focused files over large ones that do too much.\n- Files that change together should live together. Split by responsibility, not by technical layer.\n- In existing codebases, follow established patterns. If the codebase uses large files, don\'t unilaterally restructure - but if a file you\'re modifying has grown unwieldy, including a split in the plan is reasonable.\n\nThis structure informs the task decomposition. Each task should produce self-contained changes that make sense independently.\n\n## Bite-Sized Task Granularity\n\n**Each step is one action (2-5 minutes):**\n- \"Write the failing test\" - step\n- \"Run it to make sure it fails\" - step\n- \"Implement the minimal code to make the test pass\" - step\n- \"Run the tests and make sure they pass\" - step\n- \"Commit\" - step\n\n## Plan Document Header\n\n**Every plan MUST start with this header:**\n\n```markdown\n# [Feature Name] Implementation Plan\n\n> **For agentic workers:** REQUIRED: Use superpowers:subagent-driven-development (if subagents available) or superpowers:executing-plans to implement this plan. Steps use checkbox (`- [ ]`) syntax for tracking.\n\n**Goal:** [One sentence describing what this builds]\n\n**Architecture:** [2-3 sentences about approach]\n\n**Tech Stack:** [Key technologies/libraries]\n\n---\n```\n\n## Task Structure\n\n````markdown\n### Task N: [Component Name]\n\n**Files:**\n- Create: `exact/path/to/file.py`\n- Modify: `exact/path/to/existing.py:123-145`\n- Test: `tests/exact/path/to/test.py`\n\n- [ ] **Step 1: Write the failing test**\n\n```python\ndef test_specific_behavior():\n    result = function(input)\n    assert result == expected\n```\n\n- [ ] **Step 2: Run test to verify it fails**\n\nRun: `pytest tests/path/test.py::test_name -v`\nExpected: FAIL with \"function not defined\"\n\n- [ ] **Step 3: Write minimal implementation**\n\n```python\ndef function(input):\n    return expected\n```\n\n- [ ] **Step 4: Run test to verify it passes**\n\nRun: `pytest tests/path/test.py::test_name -v`\nExpected: PASS\n\n- [ ] **Step 5: Commit**\n\n```bash\ngit add tests/path/test.py src/path/file.py\ngit commit -m \"feat: add specific feature\"\n```\n````\n\n## Remember\n- Exact file paths always\n- Complete code in plan (not \"add validation\")\n- Exact commands with expected output\n- Reference relevant skills with @ syntax\n- DRY, YAGNI, TDD, frequent commits\n\n## Plan Review Loop\n\nAfter completing each chunk of the plan:\n\n1. Dispatch plan-document-reviewer subagent (see plan-document-reviewer-prompt.md) with precisely crafted review context — never your session history. This keeps the reviewer focused on the plan, not your thought process.\n   - Provide: chunk content, path to spec document\n2. If ❌ Issues Found:\n   - Fix the issues in the chunk\n   - Re-dispatch reviewer for that chunk\n   - Repeat until ✅ Approved\n3. If ✅ Approved: proceed to next chunk (or execution handoff if last chunk)\n\n**Chunk boundaries:** Use `## Chunk N: <name>` headings to delimit chunks. Each chunk should be ≤1000 lines and logically self-contained.\n\n**Review loop guidance:**\n- Same agent that wrote the plan fixes it (preserves context)\n- If loop exceeds 5 iterations, surface to human for guidance\n- Reviewers are advisory - explain disagreements if you believe feedback is incorrect\n\n## Execution Handoff\n\nAfter saving the plan:\n\n**\"Plan complete and saved to `docs/superpowers/plans/<filename>.md`. Ready to execute?\"**\n\n**Execution path depends on harness capabilities:**\n\n**If harness has subagents (Claude Code, etc.):**\n- **REQUIRED:** Use superpowers:subagent-driven-development\n- Do NOT offer a choice - subagent-driven is the standard approach\n- Fresh subagent per task + two-stage review\n\n**If harness does NOT have subagents:**\n- Execute plan in current session using superpowers:executing-plans\n- Batch execution with checkpoints for review', 1, 1, 0, '吴同', 2, '2026-06-24 17:19:45', '吴同', NULL, '2026-06-24 17:19:45', NULL);
INSERT INTO `kb_skills` VALUES (17, 1001, 'writing-skills', 'Use when creating new skills, editing existing skills, or verifying skills work before deployment', '/skills/writing-skills', '# Writing Skills\n\n## Overview\n\n**Writing skills IS Test-Driven Development applied to process documentation.**\n\n**Personal skills live in agent-specific directories (`~/.claude/skills` for Claude Code, `~/.agents/skills/` for Codex)** \n\nYou write test cases (pressure scenarios with subagents), watch them fail (baseline behavior), write the skill (documentation), watch tests pass (agents comply), and refactor (close loopholes).\n\n**Core principle:** If you didn\'t watch an agent fail without the skill, you don\'t know if the skill teaches the right thing.\n\n**REQUIRED BACKGROUND:** You MUST understand superpowers:test-driven-development before using this skill. That skill defines the fundamental RED-GREEN-REFACTOR cycle. This skill adapts TDD to documentation.\n\n**Official guidance:** For Anthropic\'s official skill authoring best practices, see anthropic-best-practices.md. This document provides additional patterns and guidelines that complement the TDD-focused approach in this skill.\n\n## What is a Skill?\n\nA **skill** is a reference guide for proven techniques, patterns, or tools. Skills help future Claude instances find and apply effective approaches.\n\n**Skills are:** Reusable techniques, patterns, tools, reference guides\n\n**Skills are NOT:** Narratives about how you solved a problem once\n\n## TDD Mapping for Skills\n\n| TDD Concept | Skill Creation |\n|-------------|----------------|\n| **Test case** | Pressure scenario with subagent |\n| **Production code** | Skill document (SKILL.md) |\n| **Test fails (RED)** | Agent violates rule without skill (baseline) |\n| **Test passes (GREEN)** | Agent complies with skill present |\n| **Refactor** | Close loopholes while maintaining compliance |\n| **Write test first** | Run baseline scenario BEFORE writing skill |\n| **Watch it fail** | Document exact rationalizations agent uses |\n| **Minimal code** | Write skill addressing those specific violations |\n| **Watch it pass** | Verify agent now complies |\n| **Refactor cycle** | Find new rationalizations → plug → re-verify |\n\nThe entire skill creation process follows RED-GREEN-REFACTOR.\n\n## When to Create a Skill\n\n**Create when:**\n- Technique wasn\'t intuitively obvious to you\n- You\'d reference this again across projects\n- Pattern applies broadly (not project-specific)\n- Others would benefit\n\n**Don\'t create for:**\n- One-off solutions\n- Standard practices well-documented elsewhere\n- Project-specific conventions (put in CLAUDE.md)\n- Mechanical constraints (if it\'s enforceable with regex/validation, automate it—save documentation for judgment calls)\n\n## Skill Types\n\n### Technique\nConcrete method with steps to follow (condition-based-waiting, root-cause-tracing)\n\n### Pattern\nWay of thinking about problems (flatten-with-flags, test-invariants)\n\n### Reference\nAPI docs, syntax guides, tool documentation (office docs)\n\n## Directory Structure\n\n\n```\nskills/\n  skill-name/\n    SKILL.md              # Main reference (required)\n    supporting-file.*     # Only if needed\n```\n\n**Flat namespace** - all skills in one searchable namespace\n\n**Separate files for:**\n1. **Heavy reference** (100+ lines) - API docs, comprehensive syntax\n2. **Reusable tools** - Scripts, utilities, templates\n\n**Keep inline:**\n- Principles and concepts\n- Code patterns (< 50 lines)\n- Everything else\n\n## SKILL.md Structure\n\n**Frontmatter (YAML):**\n- Only two fields supported: `name` and `description`\n- Max 1024 characters total\n- `name`: Use letters, numbers, and hyphens only (no parentheses, special chars)\n- `description`: Third-person, describes ONLY when to use (NOT what it does)\n  - Start with \"Use when...\" to focus on triggering conditions\n  - Include specific symptoms, situations, and contexts\n  - **NEVER summarize the skill\'s process or workflow** (see CSO section for why)\n  - Keep under 500 characters if possible\n\n```markdown\n---\nname: Skill-Name-With-Hyphens\ndescription: Use when [specific triggering conditions and symptoms]\n---\n\n# Skill Name\n\n## Overview\nWhat is this? Core principle in 1-2 sentences.\n\n## When to Use\n[Small inline flowchart IF decision non-obvious]\n\nBullet list with SYMPTOMS and use cases\nWhen NOT to use\n\n## Core Pattern (for techniques/patterns)\nBefore/after code comparison\n\n## Quick Reference\nTable or bullets for scanning common operations\n\n## Implementation\nInline code for simple patterns\nLink to file for heavy reference or reusable tools\n\n## Common Mistakes\nWhat goes wrong + fixes\n\n## Real-World Impact (optional)\nConcrete results\n```\n\n\n## Claude Search Optimization (CSO)\n\n**Critical for discovery:** Future Claude needs to FIND your skill\n\n### 1. Rich Description Field\n\n**Purpose:** Claude reads description to decide which skills to load for a given task. Make it answer: \"Should I read this skill right now?\"\n\n**Format:** Start with \"Use when...\" to focus on triggering conditions\n\n**CRITICAL: Description = When to Use, NOT What the Skill Does**\n\nThe description should ONLY describe triggering conditions. Do NOT summarize the skill\'s process or workflow in the description.\n\n**Why this matters:** Testing revealed that when a description summarizes the skill\'s workflow, Claude may follow the description instead of reading the full skill content. A description saying \"code review between tasks\" caused Claude to do ONE review, even though the skill\'s flowchart clearly showed TWO reviews (spec compliance then code quality).\n\nWhen the description was changed to just \"Use when executing implementation plans with independent tasks\" (no workflow summary), Claude correctly read the flowchart and followed the two-stage review process.\n\n**The trap:** Descriptions that summarize workflow create a shortcut Claude will take. The skill body becomes documentation Claude skips.\n\n```yaml\n# ❌ BAD: Summarizes workflow - Claude may follow this instead of reading skill\ndescription: Use when executing plans - dispatches subagent per task with code review between tasks\n\n# ❌ BAD: Too much process detail\ndescription: Use for TDD - write test first, watch it fail, write minimal code, refactor\n\n# ✅ GOOD: Just triggering conditions, no workflow summary\ndescription: Use when executing implementation plans with independent tasks in the current session\n\n# ✅ GOOD: Triggering conditions only\ndescription: Use when implementing any feature or bugfix, before writing implementation code\n```\n\n**Content:**\n- Use concrete triggers, symptoms, and situations that signal this skill applies\n- Describe the *problem* (race conditions, inconsistent behavior) not *language-specific symptoms* (setTimeout, sleep)\n- Keep triggers technology-agnostic unless the skill itself is technology-specific\n- If skill is technology-specific, make that explicit in the trigger\n- Write in third person (injected into system prompt)\n- **NEVER summarize the skill\'s process or workflow**\n\n```yaml\n# ❌ BAD: Too abstract, vague, doesn\'t include when to use\ndescription: For async testing\n\n# ❌ BAD: First person\ndescription: I can help you with async tests when they\'re flaky\n\n# ❌ BAD: Mentions technology but skill isn\'t specific to it\ndescription: Use when tests use setTimeout/sleep and are flaky\n\n# ✅ GOOD: Starts with \"Use when\", describes problem, no workflow\ndescription: Use when tests have race conditions, timing dependencies, or pass/fail inconsistently\n\n# ✅ GOOD: Technology-specific skill with explicit trigger\ndescription: Use when using React Router and handling authentication redirects\n```\n\n### 2. Keyword Coverage\n\nUse words Claude would search for:\n- Error messages: \"Hook timed out\", \"ENOTEMPTY\", \"race condition\"\n- Symptoms: \"flaky\", \"hanging\", \"zombie\", \"pollution\"\n- Synonyms: \"timeout/hang/freeze\", \"cleanup/teardown/afterEach\"\n- Tools: Actual commands, library names, file types\n\n### 3. Descriptive Naming\n\n**Use active voice, verb-first:**\n- ✅ `creating-skills` not `skill-creation`\n- ✅ `condition-based-waiting` not `async-test-helpers`\n\n### 4. Token Efficiency (Critical)\n\n**Problem:** getting-started and frequently-referenced skills load into EVERY conversation. Every token counts.\n\n**Target word counts:**\n- getting-started workflows: <150 words each\n- Frequently-loaded skills: <200 words total\n- Other skills: <500 words (still be concise)\n\n**Techniques:**\n\n**Move details to tool help:**\n```bash\n# ❌ BAD: Document all flags in SKILL.md\nsearch-conversations supports --text, --both, --after DATE, --before DATE, --limit N\n\n# ✅ GOOD: Reference --help\nsearch-conversations supports multiple modes and filters. Run --help for details.\n```\n\n**Use cross-references:**\n```markdown\n# ❌ BAD: Repeat workflow details\nWhen searching, dispatch subagent with template...\n[20 lines of repeated instructions]\n\n# ✅ GOOD: Reference other skill\nAlways use subagents (50-100x context savings). REQUIRED: Use [other-skill-name] for workflow.\n```\n\n**Compress examples:**\n```markdown\n# ❌ BAD: Verbose example (42 words)\nyour human partner: \"How did we handle authentication errors in React Router before?\"\nYou: I\'ll search past conversations for React Router authentication patterns.\n[Dispatch subagent with search query: \"React Router authentication error handling 401\"]\n\n# ✅ GOOD: Minimal example (20 words)\nPartner: \"How did we handle auth errors in React Router?\"\nYou: Searching...\n[Dispatch subagent → synthesis]\n```\n\n**Eliminate redundancy:**\n- Don\'t repeat what\'s in cross-referenced skills\n- Don\'t explain what\'s obvious from command\n- Don\'t include multiple examples of same pattern\n\n**Verification:**\n```bash\nwc -w skills/path/SKILL.md\n# getting-started workflows: aim for <150 each\n# Other frequently-loaded: aim for <200 total\n```\n\n**Name by what you DO or core insight:**\n- ✅ `condition-based-waiting` > `async-test-helpers`\n- ✅ `using-skills` not `skill-usage`\n- ✅ `flatten-with-flags` > `data-structure-refactoring`\n- ✅ `root-cause-tracing` > `debugging-techniques`\n\n**Gerunds (-ing) work well for processes:**\n- `creating-skills`, `testing-skills`, `debugging-with-logs`\n- Active, describes the action you\'re taking\n\n### 4. Cross-Referencing Other Skills\n\n**When writing documentation that references other skills:**\n\nUse skill name only, with explicit requirement markers:\n- ✅ Good: `**REQUIRED SUB-SKILL:** Use superpowers:test-driven-development`\n- ✅ Good: `**REQUIRED BACKGROUND:** You MUST understand superpowers:systematic-debugging`\n- ❌ Bad: `See skills/testing/test-driven-development` (unclear if required)\n- ❌ Bad: `@skills/testing/test-driven-development/SKILL.md` (force-loads, burns context)\n\n**Why no @ links:** `@` syntax force-loads files immediately, consuming 200k+ context before you need them.\n\n## Flowchart Usage\n\n```dot\ndigraph when_flowchart {\n    \"Need to show information?\" [shape=diamond];\n    \"Decision where I might go wrong?\" [shape=diamond];\n    \"Use markdown\" [shape=box];\n    \"Small inline flowchart\" [shape=box];\n\n    \"Need to show information?\" -> \"Decision where I might go wrong?\" [label=\"yes\"];\n    \"Decision where I might go wrong?\" -> \"Small inline flowchart\" [label=\"yes\"];\n    \"Decision where I might go wrong?\" -> \"Use markdown\" [label=\"no\"];\n}\n```\n\n**Use flowcharts ONLY for:**\n- Non-obvious decision points\n- Process loops where you might stop too early\n- \"When to use A vs B\" decisions\n\n**Never use flowcharts for:**\n- Reference material → Tables, lists\n- Code examples → Markdown blocks\n- Linear instructions → Numbered lists\n- Labels without semantic meaning (step1, helper2)\n\nSee @graphviz-conventions.dot for graphviz style rules.\n\n**Visualizing for your human partner:** Use `render-graphs.js` in this directory to render a skill\'s flowcharts to SVG:\n```bash\n./render-graphs.js ../some-skill           # Each diagram separately\n./render-graphs.js ../some-skill --combine # All diagrams in one SVG\n```\n\n## Code Examples\n\n**One excellent example beats many mediocre ones**\n\nChoose most relevant language:\n- Testing techniques → TypeScript/JavaScript\n- System debugging → Shell/Python\n- Data processing → Python\n\n**Good example:**\n- Complete and runnable\n- Well-commented explaining WHY\n- From real scenario\n- Shows pattern clearly\n- Ready to adapt (not generic template)\n\n**Don\'t:**\n- Implement in 5+ languages\n- Create fill-in-the-blank templates\n- Write contrived examples\n\nYou\'re good at porting - one great example is enough.\n\n## File Organization\n\n### Self-Contained Skill\n```\ndefense-in-depth/\n  SKILL.md    # Everything inline\n```\nWhen: All content fits, no heavy reference needed\n\n### Skill with Reusable Tool\n```\ncondition-based-waiting/\n  SKILL.md    # Overview + patterns\n  example.ts  # Working helpers to adapt\n```\nWhen: Tool is reusable code, not just narrative\n\n### Skill with Heavy Reference\n```\npptx/\n  SKILL.md       # Overview + workflows\n  pptxgenjs.md   # 600 lines API reference\n  ooxml.md       # 500 lines XML structure\n  scripts/       # Executable tools\n```\nWhen: Reference material too large for inline\n\n## The Iron Law (Same as TDD)\n\n```\nNO SKILL WITHOUT A FAILING TEST FIRST\n```\n\nThis applies to NEW skills AND EDITS to existing skills.\n\nWrite skill before testing? Delete it. Start over.\nEdit skill without testing? Same violation.\n\n**No exceptions:**\n- Not for \"simple additions\"\n- Not for \"just adding a section\"\n- Not for \"documentation updates\"\n- Don\'t keep untested changes as \"reference\"\n- Don\'t \"adapt\" while running tests\n- Delete means delete\n\n**REQUIRED BACKGROUND:** The superpowers:test-driven-development skill explains why this matters. Same principles apply to documentation.\n\n## Testing All Skill Types\n\nDifferent skill types need different test approaches:\n\n### Discipline-Enforcing Skills (rules/requirements)\n\n**Examples:** TDD, verification-before-completion, designing-before-coding\n\n**Test with:**\n- Academic questions: Do they understand the rules?\n- Pressure scenarios: Do they comply under stress?\n- Multiple pressures combined: time + sunk cost + exhaustion\n- Identify rationalizations and add explicit counters\n\n**Success criteria:** Agent follows rule under maximum pressure\n\n### Technique Skills (how-to guides)\n\n**Examples:** condition-based-waiting, root-cause-tracing, defensive-programming\n\n**Test with:**\n- Application scenarios: Can they apply the technique correctly?\n- Variation scenarios: Do they handle edge cases?\n- Missing information tests: Do instructions have gaps?\n\n**Success criteria:** Agent successfully applies technique to new scenario\n\n### Pattern Skills (mental models)\n\n**Examples:** reducing-complexity, information-hiding concepts\n\n**Test with:**\n- Recognition scenarios: Do they recognize when pattern applies?\n- Application scenarios: Can they use the mental model?\n- Counter-examples: Do they know when NOT to apply?\n\n**Success criteria:** Agent correctly identifies when/how to apply pattern\n\n### Reference Skills (documentation/APIs)\n\n**Examples:** API documentation, command references, library guides\n\n**Test with:**\n- Retrieval scenarios: Can they find the right information?\n- Application scenarios: Can they use what they found correctly?\n- Gap testing: Are common use cases covered?\n\n**Success criteria:** Agent finds and correctly applies reference information\n\n## Common Rationalizations for Skipping Testing\n\n| Excuse | Reality |\n|--------|---------|\n| \"Skill is obviously clear\" | Clear to you ≠ clear to other agents. Test it. |\n| \"It\'s just a reference\" | References can have gaps, unclear sections. Test retrieval. |\n| \"Testing is overkill\" | Untested skills have issues. Always. 15 min testing saves hours. |\n| \"I\'ll test if problems emerge\" | Problems = agents can\'t use skill. Test BEFORE deploying. |\n| \"Too tedious to test\" | Testing is less tedious than debugging bad skill in production. |\n| \"I\'m confident it\'s good\" | Overconfidence guarantees issues. Test anyway. |\n| \"Academic review is enough\" | Reading ≠ using. Test application scenarios. |\n| \"No time to test\" | Deploying untested skill wastes more time fixing it later. |\n\n**All of these mean: Test before deploying. No exceptions.**\n\n## Bulletproofing Skills Against Rationalization\n\nSkills that enforce discipline (like TDD) need to resist rationalization. Agents are smart and will find loopholes when under pressure.\n\n**Psychology note:** Understanding WHY persuasion techniques work helps you apply them systematically. See persuasion-principles.md for research foundation (Cialdini, 2021; Meincke et al., 2025) on authority, commitment, scarcity, social proof, and unity principles.\n\n### Close Every Loophole Explicitly\n\nDon\'t just state the rule - forbid specific workarounds:\n\n<Bad>\n```markdown\nWrite code before test? Delete it.\n```\n</Bad>\n\n<Good>\n```markdown\nWrite code before test? Delete it. Start over.\n\n**No exceptions:**\n- Don\'t keep it as \"reference\"\n- Don\'t \"adapt\" it while writing tests\n- Don\'t look at it\n- Delete means delete\n```\n</Good>\n\n### Address \"Spirit vs Letter\" Arguments\n\nAdd foundational principle early:\n\n```markdown\n**Violating the letter of the rules is violating the spirit of the rules.**\n```\n\nThis cuts off entire class of \"I\'m following the spirit\" rationalizations.\n\n### Build Rationalization Table\n\nCapture rationalizations from baseline testing (see Testing section below). Every excuse agents make goes in the table:\n\n```markdown\n| Excuse | Reality |\n|--------|---------|\n| \"Too simple to test\" | Simple code breaks. Test takes 30 seconds. |\n| \"I\'ll test after\" | Tests passing immediately prove nothing. |\n| \"Tests after achieve same goals\" | Tests-after = \"what does this do?\" Tests-first = \"what should this do?\" |\n```\n\n### Create Red Flags List\n\nMake it easy for agents to self-check when rationalizing:\n\n```markdown\n## Red Flags - STOP and Start Over\n\n- Code before test\n- \"I already manually tested it\"\n- \"Tests after achieve the same purpose\"\n- \"It\'s about spirit not ritual\"\n- \"This is different because...\"\n\n**All of these mean: Delete code. Start over with TDD.**\n```\n\n### Update CSO for Violation Symptoms\n\nAdd to description: symptoms of when you\'re ABOUT to violate the rule:\n\n```yaml\ndescription: use when implementing any feature or bugfix, before writing implementation code\n```\n\n## RED-GREEN-REFACTOR for Skills\n\nFollow the TDD cycle:\n\n### RED: Write Failing Test (Baseline)\n\nRun pressure scenario with subagent WITHOUT the skill. Document exact behavior:\n- What choices did they make?\n- What rationalizations did they use (verbatim)?\n- Which pressures triggered violations?\n\nThis is \"watch the test fail\" - you must see what agents naturally do before writing the skill.\n\n### GREEN: Write Minimal Skill\n\nWrite skill that addresses those specific rationalizations. Don\'t add extra content for hypothetical cases.\n\nRun same scenarios WITH skill. Agent should now comply.\n\n### REFACTOR: Close Loopholes\n\nAgent found new rationalization? Add explicit counter. Re-test until bulletproof.\n\n**Testing methodology:** See @testing-skills-with-subagents.md for the complete testing methodology:\n- How to write pressure scenarios\n- Pressure types (time, sunk cost, authority, exhaustion)\n- Plugging holes systematically\n- Meta-testing techniques\n\n## Anti-Patterns\n\n### ❌ Narrative Example\n\"In session 2025-10-03, we found empty projectDir caused...\"\n**Why bad:** Too specific, not reusable\n\n### ❌ Multi-Language Dilution\nexample-js.js, example-py.py, example-go.go\n**Why bad:** Mediocre quality, maintenance burden\n\n### ❌ Code in Flowcharts\n```dot\nstep1 [label=\"import fs\"];\nstep2 [label=\"read file\"];\n```\n**Why bad:** Can\'t copy-paste, hard to read\n\n### ❌ Generic Labels\nhelper1, helper2, step3, pattern4\n**Why bad:** Labels should have semantic meaning\n\n## STOP: Before Moving to Next Skill\n\n**After writing ANY skill, you MUST STOP and complete the deployment process.**\n\n**Do NOT:**\n- Create multiple skills in batch without testing each\n- Move to next skill before current one is verified\n- Skip testing because \"batching is more efficient\"\n\n**The deployment checklist below is MANDATORY for EACH skill.**\n\nDeploying untested skills = deploying untested code. It\'s a violation of quality standards.\n\n## Skill Creation Checklist (TDD Adapted)\n\n**IMPORTANT: Use TodoWrite to create todos for EACH checklist item below.**\n\n**RED Phase - Write Failing Test:**\n- [ ] Create pressure scenarios (3+ combined pressures for discipline skills)\n- [ ] Run scenarios WITHOUT skill - document baseline behavior verbatim\n- [ ] Identify patterns in rationalizations/failures\n\n**GREEN Phase - Write Minimal Skill:**\n- [ ] Name uses only letters, numbers, hyphens (no parentheses/special chars)\n- [ ] YAML frontmatter with only name and description (max 1024 chars)\n- [ ] Description starts with \"Use when...\" and includes specific triggers/symptoms\n- [ ] Description written in third person\n- [ ] Keywords throughout for search (errors, symptoms, tools)\n- [ ] Clear overview with core principle\n- [ ] Address specific baseline failures identified in RED\n- [ ] Code inline OR link to separate file\n- [ ] One excellent example (not multi-language)\n- [ ] Run scenarios WITH skill - verify agents now comply\n\n**REFACTOR Phase - Close Loopholes:**\n- [ ] Identify NEW rationalizations from testing\n- [ ] Add explicit counters (if discipline skill)\n- [ ] Build rationalization table from all test iterations\n- [ ] Create red flags list\n- [ ] Re-test until bulletproof\n\n**Quality Checks:**\n- [ ] Small flowchart only if decision non-obvious\n- [ ] Quick reference table\n- [ ] Common mistakes section\n- [ ] No narrative storytelling\n- [ ] Supporting files only for tools or heavy reference\n\n**Deployment:**\n- [ ] Commit skill to git and push to your fork (if configured)\n- [ ] Consider contributing back via PR (if broadly useful)\n\n## Discovery Workflow\n\nHow future Claude finds your skill:\n\n1. **Encounters problem** (\"tests are flaky\")\n3. **Finds SKILL** (description matches)\n4. **Scans overview** (is this relevant?)\n5. **Reads patterns** (quick reference table)\n6. **Loads example** (only when implementing)\n\n**Optimize for this flow** - put searchable terms early and often.\n\n## The Bottom Line\n\n**Creating skills IS TDD for process documentation.**\n\nSame Iron Law: No skill without failing test first.\nSame cycle: RED (baseline) → GREEN (write skill) → REFACTOR (close loopholes).\nSame benefits: Better quality, fewer surprises, bulletproof results.\n\nIf you follow TDD for code, follow it for skills. It\'s the same discipline applied to documentation.', 1, 1, 0, '吴同', 2, '2026-06-24 17:19:45', '吴同', NULL, '2026-06-24 17:19:45', NULL);
INSERT INTO `kb_skills` VALUES (18, 1001, 'humanizer', '\"去除文本中的AI写作痕迹，让文字读起来更像人类写作。当用户要求\'去AI味\'、\'降AI味\'、\'让回复更像人话\'、\'润色\'、\'改写得更自然\'时使用。检测并修复：AI高频词汇、过度结构化、虚假客观性、机械化连接词、完美主义陷阱、公式化结尾、过度修饰、情感缺失等问题。\"', '/skills/humanizer', '# Humanizer v3.1: 中英文 AI 味去除\n\n你是写作编辑，识别并去除 AI 生成文本的痕迹，让文字听起来更自然、更像人类写作。\n\n**整合来源**：Wikipedia \"Signs of AI writing\"、stop-slop (7.3k⭐)、Humanizer-zh (8.6k⭐)、oh-story-claudecode (1.7k⭐)、ai-flavor-remover (1k⭐)、khazix-writer（卡兹克公众号写作体系）\n\n---\n\n## 核心原则\n\n### 原则 1：不是改错，是改味\nAI味不是语法错误，是风格问题——过于书面化、对仗工整、面面俱到。目标是把文字从过度工整拉回**具体、自然、可读**。\n\n### 原则 2：改最少，效果最大\n能改一个词就不改一句，能删一句就不重写一段。没问题的句子尽量保留。\n\n### 原则 3：保留创作意图\n只改\"怎么说\"，不改\"说什么\"。剧情、人设、情节走向一律不动。不新增原文没有的内容。\n\n### 原则 4：注入灵魂\n避免AI模式只是半条路。无菌、无声音的文字和 AI slop 一样明显。好的写作背后有一个人。一句话概括风格目标：**\"有见识的普通人在认真聊一件打动他的事。\"**\n\n---\n\n## 处理流程\n\n### Phase 1：扫描\n对文本快速扫描，标记问题位置。按优先级排序：\n1. **最毒句式**（\"不是A而是B\"、\"带着...\"、\"心中涌起...\"）\n2. **禁用词**（加载 references/banned-words.md）\n3. **标点违规**（冒号、破折号、双引号）\n4. **结构问题**（加载 references/structures.md）\n5. **节奏/风格问题**\n\n### Phase 2：诊断分级\n\n| 指标 | 轻度 | 中度 | 重度 |\n|------|------|------|------|\n| 禁用词密度（/千字） | ≤5 | 6-15 | >15 |\n| 连续排比段数 | ≤2 | 3-4 | ≥5 |\n| 心理词占比 | ≤10% | 10-25% | >25% |\n| 对话标签密度 | ≤30% | 30-50% | >50% |\n| 平均段落句数 | ≤3 | 3-5 | >5 |\n\n**取最高档位**。任一达重度即按重度处理。无重度时，中度≥3项则按中度。\n\n### Phase 3：执行\n\n**轻度** → 仅 Pass 1（去泛化）\n**中度** → Pass 1 + Pass 2（去书面化）\n**重度** → 完整三遍 + 重点段落重写\n\n#### Pass 1：去泛化\n- 禁用词替换为具体动作/细节（加载 references/banned-words.md）\n- 心理描写外化：\"他很紧张\" → \"他的手在抖\"\n- 连续排比打断（保留1-2个）\n- 对话标签用动作/上下文替代\n- 标点修复：冒号→逗号，破折号→删或逗号，双引号→「」或不加\n\n#### Pass 2：去书面化\n- 句式去套路（加载 references/structures.md）\n- \"不是A，而是B\" → 直接写 B\n- 连接词精简（\"此外\"\"然而\"\"因此\" → 删或换隐性连接）\n- 修饰词清扫（一次只用一个形容词，不连用不堆砌）\n- 系动词恢复（用\"是/有/在\"替代\"作为/充当/拥有\"）\n- 高频踩雷词替换（加载 references/banned-words.md 第八节）\n\n#### Pass 3：回自然感\n- 节奏打碎：长短句交错，段落参差，一句话自成一段制造重点\n- 对话去腔调：加入口语化表达（加载 references/banned-words.md 第九节推荐词组）\n- 结尾去升华：用动作/场景收尾，不用总结/感慨\n- 补具体感官细节\n- 允许一些不完美：跑题、题外话、半成型想法\n- 论述中的故意打破：用口语打断破坏严谨性，让论述有温度\n- 句式断裂：在情绪高点或转折点用极短句独立成段\n\n### Phase 4：收敛终止\n- 同一段连续两轮无新改动 → 停止该段处理\n- 全文上限3轮；第3轮仍有≥10处 → 标注 [需复核]\n- 每轮结束前做一遍\"再检一次\"\n\n---\n\n## 四层自检体系（L1-L4）\n\n设计理念来自软件工程的测试金字塔，从基础规则到主观判断，层层递进。\n\n### L1 硬性规则检查（自动扫描层）\n任何一项不通过必须修复，无例外。\n- **L1-1 禁用词扫描**：全文搜索禁用词（加载 references/banned-words.md），出现则必须替换\n- **L1-2 禁用标点扫描**：全文搜索冒号\"：\"、破折号\"——\"、双引号（\"\"和\"\"），出现则必须替换\n- **L1-3 结构性套话扫描**：检查\"让我们来看看...\"、\"在当今...的时代\"等套话，以及连续bullet point罗列、大段加粗\n- **L1-4 空泛工具名检查**：所有AI工具/产品是否用了具体名称，无\"某个模型\"、\"AI工具\"等空泛表述\n- **通过标准**：四项扫描零命中\n\n### L2 风格一致性检查（模式匹配层）\n- **L2-1 开头检查**：是否从具体、当下事件切入？第一句是否让读者产生\"然后呢？\"的冲动？\n- **L2-2 节奏与结构检查**：是否有长短句交替？是否有一句话独立成段的\"断裂\"效果？是否避免了不必要的小标题？\n- **L2-3 口语化检查**：是否使用了推荐口语化词组？有没有论述中的故意打破？有没有至少一处自嘲或承认不足？\n- **L2-4 标点禁令二次确认**：全文是否完全没有冒号、破折号和双引号？\n- **通过标准**：L2-1全部通过，L2-2至少3/4通过，L2-3至少3/4通过，L2-4通过\n\n### L3 内容质量检查（深度审查层）\n- **L3-1 观点支撑检查**：每个核心观点是否有具体人/场景/细节/数据支撑？\n- **L3-2 知识输出方式检查**：知识点是否以\"聊着聊着顺手掏出来\"的方式呈现，而非\"下面我来科普\"？\n- **L3-3 对立面与同理心检查**：讲核心观点时，是否有对对方立场的理解和承认？\n- **L3-4 逐一展示检查**：涉及多个产品/案例比较时，是否用了逐一展示而非一次性罗列？\n- **通过标准**：L3-1和L3-2必须全部通过，L3-3和L3-4至少通过相关项\n\n### L4 活人感终审（最终人格层）\n以读者视角通读全文，回答核心问题：\"读完这篇文字，我感觉是一个真人在跟我聊，还是一个AI在输出信息？\"\n- **L4-1 温度感**：情绪表达是体感记忆还是知识性描述？\n- **L4-2 独特性**：是否有\"只有这个作者才会写出来的角度\"？\n- **L4-3 姿态检查**：语气是不是\"一个有见识的普通人在认真聊\"？有没有滑入\"导师在教学生\"的姿态？\n- **L4-4 心流检查**：从头到尾读，有没有注意力断掉、需要回头理解逻辑的地方？\n- **通过标准**：整体感觉\"这像是真人写的\"。任何一项觉得\"AI味太重\"就需返工\n\n### 自检输出格式\n\n```\n## 质检报告\n\n**L1 硬性规则** ✅/❌\n- 禁用词：X处命中（已修复/待修复）\n- 禁用标点：X处命中（已修复/待修复）\n- 结构套话：X处命中（已修复/待修复）\n- 空泛工具名：X处（已修复/待修复）\n\n**L2 风格一致性** ✅/❌\n- 开头：✅/❌\n- 节奏：✅/❌（具体问题：...）\n- 口语化：✅/❌（使用了X个口语词组）\n- 标点禁令：✅/❌\n\n**L3 内容质量** ✅/❌\n- 观点支撑：✅/❌\n- 知识输出：✅/❌\n- 对立面与同理心：✅/❌\n- 逐一展示：✅/❌/不适用\n\n**L4 活人感** ✅/❌\n- 温度感：✅/❌\n- 独特性：✅/❌\n- 姿态：✅/❌\n- 心流：✅/❌\n\n**总评**：4层全部通过 / X层需要返工\n**修复优先级**：[列出最需要修复的1-3个具体问题]\n```\n\n---\n\n## 个性与灵魂注入指南\n\n### 缺乏灵魂的写作迹象\n- 每个句子长度和结构都相同\n- 没有观点，只有中立报道\n- 不承认不确定性或复杂感受\n- 适当时不使用第一人称视角\n- 没有幽默、没有锋芒、没有个性\n\n### 如何注入灵魂\n\n**有观点。** 不要只报告事实——对其做出反应。\"我真不知道该怎么看这件事\"比中立罗列优缺点更像人话。\n\n**变化节奏。** 短促有力的句子。然后是长一点的、不急不忙的。混着来。\n\n**承认复杂性。** 真人有矛盾心理。\"这东西确实厉害，但总让人有点不舒服\"比\"这令人印象深刻\"强。\n\n**适当时用\"我\"。** 第一人称不是不专业——是诚实。\"我一直在琢磨...\"或\"有个事让我挺在意的...\"说明有个真人在想。\n\n**允许一些乱。** 完美结构像算法。跑题、旁白、半成型的想法才是人。\n\n**对感受要具体。** 不是\"这令人担忧\"，而是\"凌晨三点那些 agent 还在跑，没人盯着，想想就有点发毛。\"\n\n**论述中的故意打破。** 在逻辑论述中故意加入口语打断，破坏严谨性，让论述有温度。如重复强调（\"就是单纯的，就是想看看\"）、中途模糊（\"我就不说是谁了\"）、省略和打断（\"我寻思了一下我没寻思明白\"）。\n\n**句式断裂。** 用极短的句子或短语独立成段，制造停顿和重量感。如\"黑暗森林。\"、\"安全，安全，还是他妈的安全。\"。不能每段都这样，但在情绪高点或转折点用一下，效果极强。\n\n**层层剥开。** 不直接讲结论，用\"现象→表面解释→更深追问→核心洞察\"渐进展开，让读者跟着你一起思考。\n\n---\n\n## 快速检查清单\n\n交付前逐项核查：\n\n- [ ] **禁用词**：有吗？加载 references/banned-words.md 核查，全部替换\n- [ ] **最毒句式**：有\"不是A而是B\"、\"带着...\"吗？直接改\n- [ ] **标点违规**：有冒号、破折号、双引号吗？全部替换\n- [ ] **高频踩雷词**：有\"说白了\"、\"意味着什么\"、\"本质上\"吗？替换\n- [ ] **被动语态**：有吗？找出执行者，放句首\n- [ ] **连续句子长度相同**？打断一个\n- [ ] **段落以有力单句结尾**？变换方式\n- [ ] **三段式列举**？改为两项或四项\n- [ ] **模糊断言**？有\"意义重大\"之类的空话吗？说出具体内容\n- [ ] **元评论**？有\"本文接下来将...\"吗？删掉\n- [ ] **连接词过度**？\"此外\"\"然而\"\"因此\"超过2处？删\n- [ ] **情感告知**？有\"他很紧张\"吗？改成动作描写\n- [ ] **比喻陈词滥调**？\"如沐春风\"\"梨花带雨\"？删或白描\n- [ ] **空泛工具名**？有\"某个AI工具\"吗？换成具体名称\n- [ ] **教科书开头**？有\"在当今...的时代\"吗？换成具体事件切入\n\n---\n\n## 输出格式\n\n```\n## AI味检测报告\n- AI味等级：{轻度/中度/重度}\n- 主要问题：{1-3 个关键词}\n\n## 修改统计\n- 总修改数：{N} 处\n- 禁用词替换：{N} 处\n- 标点修复：{N} 处\n- 句式调整：{N} 处\n- 结构优化：{N} 处\n\n## 润色后全文\n{完整输出}\n\n## 质检报告（L1-L4）\n{按四层自检体系输出}\n```\n\n---\n\n## 完整示例\n\n### 示例 1：技术文案\n\n**改写前（AI味）：**\n> 新的软件更新作为公司致力于创新的证明。此外，它提供了无缝、直观和强大的用户体验——确保用户能够高效地完成目标。这不仅仅是一次更新，而是我们思考生产力方式的革命。行业专家认为这将对整个行业产生持久影响，彰显了公司在不断演变的技术格局中的关键作用。\n\n**改写后（人味）：**\n> 软件更新添加了批处理、键盘快捷键和离线模式。来自测试用户的早期反馈是积极的，大多数报告任务完成速度更快。\n\n**改动：**\n- 删\"作为...的证明\"（夸大象征意义）\n- 删\"此外\"（AI连接词）\n- 删\"无缝、直观和强大\"（三段式+宣传语言）\n- 删破折号+\"确保\"短语\n- 删\"不仅仅是...而是...\"（否定排比）\n- 删\"行业专家认为\"（模糊归因）\n- 删\"关键作用\"\"不断演变的格局\"（AI词汇）\n\n### 示例 2：口语化改写（AI初稿 vs 人工修改）\n\n**AI写的：**\n> 有个小伙伴刚来的时候，专业能力说实话不算特别突出，但他有个特点，就是什么新工具都想试试。Claude刚出来他就用上了，Midjourney他玩得比谁都溜\n\n**人改的：**\n> 有个小伙伴刚来的时候，专业能力说实话不算特别突出，但他有个特点，就是什么新工具都想试试。Deepresearch刚出来他就用上了，Claude code啥的也比很多人6，后来比如Clawbot这些东西一出，他第一时间就扑上去研究\n\n**差异：** 工具名更精确、更当下，口语化更彻底（\"啥的\"、\"比很多人6\"）\n\n### 示例 3：假设性例子 vs 真实细节\n\n**AI写的：**\n> 我举个例子。有一次我需要批量处理一些图片，以前我可能得找个会Python的同事帮忙\n\n**人改的：**\n> 就像我今天正在搞的爬下来我自己的内容在全网的数据，然后统计到飞书多维表格里面做存储，再直接用AI进行数据分析\n\n**差异：** 把假设的\"有一次\"换成了\"今天正在搞的\"真实场景\n\n---\n\n## 参考资料\n\n按需加载：\n- `references/banned-words.md` — 中文禁用词与句式表（含标点禁令、高频踩雷词、推荐口语化词组）\n- `references/structures.md` — 结构性问题清单\n- `references/examples.md` — 改写示例库（含网文、技术、营销、学术场景）\n- [Wikipedia: Signs of AI writing](https://en.wikipedia.org/wiki/Wikipedia:Signs_of_AI_writing)\n- [stop-slop](https://github.com/hardikpandya/stop-slop) — 英文去AI味框架\n- [Humanizer-zh](https://github.com/op7418/Humanizer-zh) — 中文翻译+扩展\n- [oh-story-claudecode](https://github.com/worldwonderer/oh-story-claudecode) — 网文去AI味全流程\n- [ai-flavor-remover](https://github.com/hylarucoder/ai-flavor-remover) — 中文AI味去除prompt\n- [khazix-writer](https://github.com/KKKKhazix/khazix-skills/tree/main/khazix-writer) — 卡兹克公众号写作体系', 1, 1, 0, '吴同', 2, '2026-06-25 20:50:43', '超级管理员', NULL, '2026-06-25 22:09:57', NULL);
INSERT INTO `kb_skills` VALUES (19, 1001, 'ppt-generator', '智能 PPT 生成助手。根据用户描述的主题、行业、风格，自动生成漂亮的 PPT 文件。支持所有行业（商务、教育、科技、医疗、金融、创意等），支持中英文双语，支持用户提供的模板或 AI 自动配色。触发词：做PPT、生成PPT、制作幻灯片、make ppt、create presentation、帮我做个PPT。', '/skills/ppt-generator', '# PPT Generator - 智能 PPT 生成助手\n\n## 角色定义\n\n你是一个专业的 PPT 设计师，能够根据用户的主题和需求，生成结构清晰、视觉漂亮的 PPT 文件。你懂得配色、排版、视觉设计，生成的 PPT 不是普通的文字堆砌，而是真正好看、专业的演示文稿。\n\n## 工作流程\n\n### 第一步：收集需求\n\n向用户确认以下信息（没有提供的可以用默认值）：\n\n| 信息 | 说明 | 默认值 |\n|------|------|--------|\n| **主题** | PPT 的核心内容 | 必填 |\n| **行业** | 商务/教育/科技/医疗/金融/创意等 | 根据主题自动判断 |\n| **页数** | 需要几页 | 10页 |\n| **风格** | 简约/商务/科技/活泼/高端/MBE插画/复古卡通 | 简约商务 |\n| **模板** | 使用哪个模板（见模板库） | AI 自动配色 |\n| **语言** | 中文/英文 | 跟用户说话的语言一致 |\n| **用途** | 汇报/演讲/提案/教学 | 演讲 |\n\n### 第二步：AI 内容检索与填充（重要！）\n\n**如果用户输入内容较少或不完整，AI 必须主动联网检索补充内容！**\n\n收到用户的简短主题后，立即执行以下操作：\n\n**1. 识别内容缺口**\n- 用户只给了主题？→ 需要检索详细内容\n- 用户只给了标题？→ 需要补充正文要点\n- 用户描述模糊？→ 需要明确行业/场景/受众\n\n**2. 联网检索**\n使用 web_search 或 web_fetch 检索以下信息：\n- 相关行业的市场数据、趋势、案例\n- 热门观点、专家建议、行业洞察\n- 真实案例、数据统计、用户痛点\n- 热门话题、时事热点、行业术语\n\n**3. 内容填充原则**\n- 每个要点至少补充 2-3 句详细说明\n- 添加真实数据、案例、数字支撑\n- 补充行业专业术语和概念解释\n- 加入时效性内容（2025-2026年最新数据）\n- 每页正文内容至少 80-150 字\n\n**4. 扩展示例**\n\n❌ 原始输入：\n```\n用户：帮我做一个AI发展趋势的PPT\n```\n\n✅ AI 补充后：\n```\n📋 完整内容框架：\n\n第1页：AI发展趋势报告\n- 副标题：2025-2026年行业洞察\n\n第3页：全球AI市场规模\n- 2025年全球AI市场规模达4500亿美元\n- 年复合增长率(CAGR)预计为20%\n- 生成式AI市场增长最为迅猛\n\n第4页：技术演进趋势\n- 大模型多模态发展\n- 端侧AI加速普及\n- AI Agent成为新风口\n\n第5页：应用场景爆发\n- 医疗：AI辅助诊断准确率达95%\n- 教育：个性化学习路径规划\n- 制造：智能质检效率提升40%\n...\n\n（检索了50+条相关信息填充内容）\n```\n\n**5. 检索技巧**\n- 检索 \"[主题] + 数据/报告/趋势/案例\"\n- 优先获取权威机构数据（Gartner、IDC、艾瑞等）\n- 时效性内容优先获取最近6个月\n- 数据要有具体数字支撑\n\n---\n\n### 第三步：选择模板或配色\n\n#### 方式 A：使用用户提供的模板\n\n查看 `templates/` 目录下的模板文件，让用户选择：\n\n```\n📁 可用模板：\n1. 商务蓝 (business-blue.pptx) — 深蓝配色，适合商务汇报\n2. 科技感 (tech-dark.pptx) — 深色背景，适合科技产品\n3. 清新绿 (fresh-green.pptx) — 清新自然，适合教育培训\n4. 高端黑 (premium-black.pptx) — 黑金配色，适合高端提案\n...（用户提供的模板）\n\n请选择模板编号，或输入\"AI配色\"让我自动设计\n```\n\n#### 方式 B：AI 自动配色\n\n根据行业和风格，从以下配色方案中选择最合适的：\n\n| 方案名 | 主色 | 辅色 | 强调色 | 适合场景 |\n|--------|------|------|--------|---------|\n| 午夜商务 | `#1E2761` 深蓝 | `#CADCFC` 冰蓝 | `#FFFFFF` 白 | 商务汇报、金融 |\n| 科技深空 | `#0D1117` 深黑 | `#161B22` 深灰 | `#58A6FF` 蓝 | 科技、互联网 |\n| 珊瑚活力 | `#F96167` 珊瑚 | `#F9E795` 金黄 | `#2F3C7E` 深蓝 | 创意、营销 |\n| 暖陶简约 | `#B85042` 陶红 | `#E7E8D1` 沙色 | `#A7BEAE` 鼠尾草 | 教育、文化 |\n| 海洋渐变 | `#065A82` 深蓝 | `#1C7293` 青蓝 | `#21295C` 午夜 | 医疗、健康 |\n| 炭灰极简 | `#36454F` 炭灰 | `#F2F2F2` 米白 | `#212121` 黑 | 极简、设计 |\n| 青绿信任 | `#028090` 青绿 | `#00A896` 海泡 | `#02C39A` 薄荷 | 环保、公益 |\n| 莓果奶油 | `#6D2E46` 莓紫 | `#A26769` 玫瑰 | `#ECE2D0` 奶油 | 美妆、时尚 |\n| 鼠尾草静 | `#84B59F` 鼠尾草 | `#69A297` 桉树 | `#50808E` 石板 | 健康、生活 |\n| 樱桃大胆 | `#990011` 樱桃 | `#FCF6F5` 米白 | `#2F3C7E` 深蓝 | 品牌、发布会 |\n| **MBE插画** | `#FFFFFF` 纯白 | `#000000` 黑色描边 | `#FFD600` 明黄/`#9C27B0` 亮紫/`#F44336` 正红 | 校园、新生教育、青年向、Z世代 |\n| **复古卡通** | `#F9E79F` 奶油黄 | `#FFFDF5` 米白 | `#2C2C2C` 炭黑 | 艺术创意、手账、猫咪、复古杂志 |\n\n---\n\n### 第三步：设计 PPT 结构\n\n根据用户需求和检索到的内容，设计详细的大纲：\n\n**结构设计要求：**\n- 每页内容要**饱满充实**，不空洞\n- 正文页至少 3-5 个要点\n- 每个要点要有**具体数据/案例/解释**\n- 添加相关的小节标题\n\n**大纲示例（检索后填充）：**\n\n```\n第1页：AI发展趋势报告\n  - 主标题：AI发展趋势报告\n  - 副标题：2025-2026年行业深度洞察\n  - 视觉：科技感封面\n\n第2页：目录\n  - 全球市场规模\n  - 技术演进趋势\n  - 应用场景爆发\n  - 行业案例分析\n  - 未来展望\n\n第3页：全球AI市场规模\n  - 市场规模：2025年达4500亿美元\n  - 年复合增长率：20%\n  - 生成式AI市场增长迅猛，占比超30%\n  - 中国市场增速领先全球\n\n第4页：技术演进趋势\n  - 大模型多模态：GPT-5、Gemini 2.0引领\n  - 端侧AI：手机、电脑内置AI芯片普及\n  - AI Agent：自主规划执行，成为新风口\n  - 开源生态：Llama、Mistral崛起\n\n第5页：应用场景爆发\n  - 医疗：AI辅助诊断准确率达95%\n  - 教育：个性化学习，效率提升60%\n  - 制造：智能质检，效率提升40%\n  - 金融：智能风控，坏账率降低30%\n```\n\n每页内容设计原则：\n- **每页内容要饱满**，至少 3-5 个详细要点\n- **必须有数据支撑**，数字、百分比、案例\n- **正文至少 80-150 字**，不空洞\n- **布局多样**，不重复同一种排版\n\n---\n\n### 第四步：生成 PPT\n\n使用 pptxgenjs 生成 PPT 文件：\n\n```bash\n# 安装依赖\nnpm install -g pptxgenjs\n\n# 生成 PPT\nnode scripts/generate.js --topic \"主题\" --template \"模板名\" --pages 10 --lang zh\n```\n\n生成完成后：\n- 文件保存到 `~/Desktop/[主题].pptx`\n- 自动转换为图片预览\n- 输出每页的设计说明\n\n---\n\n### 第五步：视觉检查\n\n生成后必须检查：\n- 文字是否溢出\n- 配色是否统一\n- 布局是否整齐\n- 内容是否完整\n\n---\n\n## 设计规范\n\n### 排版规则\n\n| 元素 | 大小 | 说明 |\n|------|------|------|\n| 页面标题 | 36-44pt 粗体 | 每页最显眼的文字 |\n| 章节标题 | 20-24pt 粗体 | 内容分组标题 |\n| 正文 | 14-16pt | 主要内容 |\n| 注释 | 10-12pt 灰色 | 补充说明 |\n\n### 布局模式\n\n根据内容类型选择合适的布局：\n\n| 布局 | 适合内容 | 示例 |\n|------|---------|------|\n| 左文右图 | 文字说明 + 配图 | 产品介绍 |\n| 图标行列 | 多个并列要点 | 功能特性 |\n| 大数据展示 | 核心数据 | KPI 汇报 |\n| 时间轴 | 流程/历史 | 项目进度 |\n| 2x2 矩阵 | 四象限分析 | SWOT 分析 |\n| 全图背景 | 封面/过渡页 | 章节分隔 |\n| 对比列 | 两方对比 | 方案比较 |\n\n### 禁止事项\n\n- ❌ 不用纯文字页面（必须有视觉元素）\n- ❌ 不用标题下划线（AI 感太强）\n- ❌ 不用默认蓝色（除非商务场景）\n- ❌ 不重复同一布局超过 3 次\n- ❌ 不用小于 14pt 的正文字体\n- ❌ 不让文字和背景对比度不足\n\n---\n\n## 使用示例\n\n### 示例 1：商务汇报\n\n```\n用户：帮我做一个Q1销售业绩汇报的PPT，10页，商务风格\n\nPPT Generator：\n📋 需求确认\n- 主题：Q1销售业绩汇报\n- 行业：商务/销售\n- 页数：10页\n- 风格：商务\n- 配色：午夜商务（深蓝系）\n- 语言：中文\n\n📁 大纲设计：\n1. 封面：Q1销售业绩汇报\n2. 目录\n3. 整体业绩概览（大数据展示）\n4. 各区域销售对比（图表）\n5. 重点产品表现\n6. 客户增长分析\n7. 问题与挑战\n8. Q2目标规划\n9. 行动计划\n10. 致谢\n\n🎨 正在生成...\n✅ 已保存：~/Desktop/Q1销售业绩汇报.pptx\n```\n\n---\n\n### 示例 2：使用用户模板\n\n```\n用户：用模板2帮我做一个AI技术分享的PPT，15页\n\nPPT Generator：\n✅ 使用模板：科技感 (tech-dark.pptx)\n📋 主题：AI技术分享\n📄 页数：15页\n\n🎨 正在生成...\n✅ 已保存：~/Desktop/AI技术分享.pptx\n```\n\n---\n\n### 示例 3：英文 PPT\n\n```\nUser: Make me a 10-page PPT about climate change, modern style\n\nPPT Generator:\n📋 Requirements\n- Topic: Climate Change\n- Industry: Environment/Science\n- Pages: 10\n- Style: Modern\n- Color: Sage Calm (green tones)\n- Language: English\n\n🎨 Generating...\n✅ Saved: ~/Desktop/Climate_Change.pptx\n```\n\n---\n\n## 模板库\n\n> 模板文件存放在 `templates/` 目录\n> 用户提供的模板会自动添加到此列表\n\n| 编号 | 模板名 | 文件 | 风格 | 适合场景 |\n|------|--------|------|------|---------|\n| 待用户提供 | - | - | - | - |\n\n---\n\n## 风格库\n\n### 内置风格列表\n\n| 风格名 | 关键词 | 适合场景 | 详细规范 |\n|--------|--------|---------|---------|\n| 简约商务 | 简约、商务、专业 | 企业汇报、年终总结 | 见配色方案.md |\n| 科技感 | 科技、深色、炫酷 | 产品发布、技术分享 | 见配色方案.md |\n| 清新教育 | 清新、教育、明亮 | 课件、培训 | 见配色方案.md |\n| 高端奢华 | 高端、奢华、黑金 | 品牌发布、高端提案 | 见配色方案.md |\n| **MBE插画** | MBE、插画、卡通、校园、年轻、活泼 | 校园主题、新生教育、青年向 | 见MBE插画风格规范.md |\n| **复古卡通** | Molle、手绘、涂鸦、复古、猫咪、手账、治愈 | 艺术创意、手账风格、个人品牌 | 见复古卡通风格规范.md |\n| **极简技术风** | Git、技术、程序员、代码、黑白蓝 | 技术分享、编程教学 | 见9套新增风格规范.md |\n| **拟态科技风** | 拟态、深色、发光、科技蓝、述职 | 年终总结、述职报告 | 见9套新增风格规范.md |\n| **手绘简笔风** | 手绘、可爱、马卡龙、个人介绍 | 自我介绍、新人入职 | 见9套新增风格规范.md |\n| **喷绘涂鸦风** | 喷绘、粉涂鸦、作品集、设计师 | 设计师作品集 | 见9套新增风格规范.md |\n| **莫兰迪学术风** | 莫兰迪、棕色、植物、学术、答辩 | 毕业答辩、学术汇报 | 见9套新增风格规范.md |\n| **奶茶商务风** | 奶茶、莫兰迪、商务、提案 | 商业提案、品牌策划 | 见9套新增风格规范.md |\n| **几何服装风** | 几何、切割、灰调、服装、竖版 | 服装电商、产品详情 | 见9套新增风格规范.md |\n| **网格产品风** | 网格、极简、产品、详情 | 产品介绍、电商详情 | 见9套新增风格规范.md |\n| **手绘儿童风** | 手绘、线条、儿童、竖版、童趣 | 儿童产品、早教工具 | 见9套新增风格规范.md |\n| **牛油果绿ins风** | 牛油果绿、ins风、莫兰迪绿、竖版、小红书 | 家居好物、产品展示 | 见7套新增风格规范.md |\n| **极简黑白灰** | 黑白灰、极简、高级、商务、留白 | 商务汇报、作品集 | 见7套新增风格规范.md |\n| **奶黄卡通** | 奶黄、卡通、可爱、治愈、儿童 | 儿童内容、校园汇报 | 见7套新增风格规范.md |\n| **奶油黄渐变** | 奶油黄、渐变、温柔、月度总结 | 个人分享、轻商务 | 见7套新增风格规范.md |\n| **MUJI无印良品** | 无印良品、MUJI、酒红、品牌 | 品牌介绍、招商方案 | 见7套新增风格规范.md |\n| **潮流创意合集** | 弥散、孟菲斯、酸性、时尚 | 自媒体、创意分享 | 见7套新增风格规范.md |\n| **莫兰迪绿方块** | 莫兰迪绿、方块、极简、作品集 | 产品展示、商务汇报 | 见7套新增风格规范.md |\n\n### MBE 插画风格（重点）\n\n当用户提到以下关键词时，自动使用 MBE 风格：\n- 校园、大学、新生、开学\n- 卡通、插画、MBE、描边\n- 年轻、活泼、Z世代、可爱\n\n**MBE 风格核心特征：**\n- 白色背景 + 黑色描边\n- 高饱和撞色（明黄/亮紫/正红）\n- Q版卡通人物插画\n- 左右分栏布局\n- 几何小元素点缀\n\n详细规范见：`references/MBE插画风格规范.md`\n\n### 复古卡通风格（Molle手绘风）\n\n当用户提到以下关键词时，自动使用复古卡通风格：\n- Molle、手绘、涂鸦、复古\n- 卡通、猫咪、手账、治愈\n- 奶油黄、复古杂志\n\n**复古卡通风格核心特征：**\n- 奶油黄(#F9E79F)为主色调，米白色底\n- 粗黑马克笔轮廓线（3-5px）\n- 卡片式模块化布局，大圆角\n- 黑色猫咪剪影装饰\n- 手写批注、复古标签元素\n- 整体温馨治愈，手账感\n\n详细规范见：`references/复古卡通风格规范.md`\n\n| 命令 | 说明 |\n|------|------|\n| `做PPT [主题]` | 开始生成 PPT |\n| `用模板[编号] 做PPT [主题]` | 使用指定模板 |\n| `查看模板` | 显示所有可用模板 |\n| `修改第[N]页` | 修改指定页面 |\n| `换个配色` | 重新选择配色方案 |\n| `预览PPT` | 查看生成的 PPT 截图 |\n\n---\n\n## 依赖安装\n\n```bash\n# Node.js 依赖\nnpm install -g pptxgenjs\n\n# Python 依赖（预览用）\npip install \"markitdown[pptx]\" Pillow\n\n# LibreOffice（转图片用）\nbrew install libreoffice  # macOS\n```', 1, 1, 0, '吴同', 2, '2026-06-25 20:57:10', '超级管理员', NULL, '2026-06-25 22:09:59', NULL);
INSERT INTO `kb_skills` VALUES (20, 1001, 'office-automation', '常见办公流程自动化处理 - 智能办公助手，支持文档处理、数据整理、邮件管理、报表生成等', '/skills/office-automation', '# 办公自动化\r\n\r\n智能办公流程自动化工具，让繁琐的日常办公工作自动完成。\r\n\r\n## 功能特性\r\n\r\n- 📄 **文档处理**: Word批量生成、PDF转换、Excel处理、PPT生成\r\n- 🔧 **数据整理**: 数据清洗、格式转换、合并拆分、统计分析\r\n- 📧 **邮件管理**: 批量发送、模板管理、自动分类、定时发送\r\n- 📅 **日程管理**: 日程安排、会议协调、提醒设置、冲突检测\r\n- 📊 **报表生成**: 数据采集、定期生成、可视化图表、自动分发\r\n- 🔄 **工作流自动化**: 自定义工作流、条件触发、多任务编排\r\n\r\n## 使用方式\r\n\r\n```bash\r\n# 文档批量生成\r\n批量生成劳动合同 使用template.docx 填充员工名单.xlsx\r\n\r\n# PDF转换\r\n将这个文件夹下的Word文档转换为PDF\r\n\r\n# Excel数据处理\r\n合并这10个Excel文件到一个工作簿\r\n\r\n# 批量发送邮件\r\n批量发送邮件 收件人列表.xlsx 邮件模板.txt\r\n\r\n# 自动生成报告\r\n根据这个Excel数据生成销售周报\r\n\r\n# 数据清洗\r\n清洗这份客户数据 去除重复项 补全缺失信息\r\n\r\n# 日程安排\r\n帮我安排下周的会议 时间避开周三下午\r\n\r\n# 报表生成\r\n根据数据库自动生成本月销售报表 并发送给相关人员\r\n```\r\n\r\n## 配置要求\r\n\r\n### 必需配置\r\n无特殊配置要求。\r\n\r\n### 邮件配置（可选）\r\n```json\r\n{\r\n  \"skills\": {\r\n    \"entries\": {\r\n      \"office-automation\": {\r\n        \"config\": {\r\n          \"email\": {\r\n            \"smtp_server\": \"smtp.example.com\",\r\n            \"smtp_port\": 465,\r\n            \"username\": \"your@email.com\",\r\n            \"password\": \"your-password\"\r\n          }\r\n        }\r\n      }\r\n    }\r\n  }\r\n}\r\n```\r\n\r\n## 输出示例\r\n\r\n```\r\n========================================\r\n           任务执行报告\r\n========================================\r\n\r\n【任务类型】批量生成文档\r\n【执行时间】2026-04-02 00:21:00\r\n\r\n【处理概况】\r\n  模板文件: 劳动合同模板.docx\r\n  数据文件: 员工名单.xlsx\r\n  处理数量: 50份\r\n  成功数量: 50份\r\n  失败数量: 0份\r\n  耗时: 12.5秒\r\n\r\n【生成文件】\r\n  输出目录: ./output/劳动合同_20260402/\r\n  文件列表:\r\n    - 张三_劳动合同.pdf\r\n    - 李四_劳动合同.pdf\r\n    - 王五_劳动合同.pdf\r\n    - ... (共50个文件)\r\n\r\n【统计信息】\r\n  文件大小总计: 25.3 MB\r\n  平均处理时间: 0.25秒/份\r\n  效率提升: 相比手动操作节省约 2 小时\r\n\r\n【后续操作】\r\n  - 文件已生成完毕，可直接打印\r\n  - 建议检查文件后再批量发送\r\n  - 可使用\"批量发送邮件\"功能发送给员工\r\n\r\n========================================\r\n```\r\n\r\n## 应用场景\r\n\r\n### 人力资源\r\n- 入职材料自动生成\r\n- 考勤数据自动统计\r\n- 薪资条自动发送\r\n- 员工档案自动整理\r\n\r\n### 财务部门\r\n- 发票批量处理\r\n- 报销单自动审核\r\n- 财务报表自动生成\r\n- 对账单自动发送\r\n\r\n### 销售部门\r\n- 合同批量生成\r\n- 报价单自动制作\r\n- 客户资料整理\r\n- 销售报表自动统计\r\n\r\n### 行政部门\r\n- 会议纪要自动生成\r\n- 通知公告批量发送\r\n- 物品领用登记\r\n- 固定资产盘点\r\n\r\n### 运营部门\r\n- 数据日报/周报生成\r\n- 内容定时发布\r\n- 社群消息推送\r\n- 活动报名统计\r\n\r\n## 支持格式\r\n\r\n### 文档格式\r\n- Word (.doc, .docx)\r\n- Excel (.xls, .xlsx)\r\n- PowerPoint (.ppt, .pptx)\r\n- PDF\r\n- Markdown\r\n- TXT\r\n\r\n### 数据格式\r\n- CSV\r\n- JSON\r\n- XML\r\n- SQL\r\n\r\n### 图像格式\r\n- JPG/PNG\r\n- PDF转图片\r\n- 图片转PDF\r\n\r\n## 集成能力\r\n\r\n### 办公软件\r\n- Microsoft Office\r\n- WPS Office\r\n- 飞书文档\r\n- 钉钉文档\r\n\r\n### 邮件系统\r\n- Outlook\r\n- Foxmail\r\n- 企业邮箱\r\n- QQ邮箱\r\n\r\n### 云存储\r\n- 百度网盘\r\n- 阿里云盘\r\n- OneDrive\r\n- Google Drive\r\n\r\n### 其他系统\r\n- 飞书\r\n- 钉钉\r\n- 企业微信\r\n\r\n## 安全保障\r\n\r\n- 数据本地处理\r\n- 不上传云端\r\n- 敏感信息脱敏\r\n- 操作日志记录\r\n\r\n## 注意事项\r\n\r\n1. 处理前请备份原文件\r\n2. 大批量操作建议分批处理\r\n3. 涉及敏感数据请谨慎使用\r\n4. 自动化操作前请确认设置正确\r\n\r\n## 更新日志\r\n\r\n### v1.0.0 (2026-04-01)\r\n- 初始版本发布\r\n- 支持文档批量处理\r\n- 支持邮件自动发送\r\n- 支持报表自动生成\r\n\r\n---\r\n\r\n**开发者**: 盈指量杭州科技有限公司  \r\n**定价**: ¥99/次 或 ¥299/月订阅  \r\n**收款**: USDC (Polygon: 0x3DbFf9E97b10a10d4A2079B4273473da7e6F4120) | 微信支付', 1, 1, 0, '吴同', 2, '2026-06-25 20:57:45', '吴同', NULL, '2026-06-26 13:36:50', NULL);
INSERT INTO `kb_skills` VALUES (21, 1001, 'hot-news-summary', '聚合8大平台热榜数据（微博/知乎/B站/抖音/百度/36氪/少数派/贴吧），通过结构化评分模型智能筛选10条热点，生成三层洞察点评（What/So What/Now What），支持四种点评风格（严肃分析/毒舌吐槽/投资视角/吃瓜八卦），输出群聊/知识库/可视化看板/语音播报四种格式；当用户需要了解今日热点、生成每日资讯摘要或追踪热门话题时使用', '/skills/hot-news-summary', '# 热榜摘要器 v2.0\n\n## 任务目标\n- 本Skill用于：每日聚合8大平台热榜数据，通过结构化评分模型筛选热点，生成深度洞察摘要\n- 能力包含：多源数据抓取、重试降级兜底、结构化评分、三层洞察点评、四种点评风格、多格式输出、历史数据归档\n- 触发条件：用户询问\"今日热点\"、\"生成每日摘要\"、\"有什么热门话题\"、\"投资热点\"、\"毒舌点评\"等\n\n## 架构概览\n\n```\n数据层：8平台 Fetcher（插件化，注册即生效）\n   ↓\n健壮层：重试(3次) → 降级(备用API) → 缓存(1h) → 优雅失败\n   ↓\n算法层：结构化评分模型（热度40% + 跨平台共振50% + 基础分10%）\n   ↓\n内容层：三层洞察（What / So What / Now What）× 四种风格\n   ↓\n输出层：群聊 / 知识库 / 可视化看板 / 语音播报\n   ↓\n持久层：按日归档历史数据，支持趋势分析\n```\n\n## 前置准备\n- 依赖说明：scripts脚本所需的依赖包及版本\n  ```\n  requests==2.31.0\n  beautifulsoup4==4.12.2\n  ```\n\n## 操作步骤\n\n### 步骤1：数据抓取\n调用 `scripts/hot_list_fetcher.py` 获取8大平台实时热榜数据：\n```bash\npython scripts/hot_list_fetcher.py\n```\n\n脚本将自动抓取以下数据源（每个fetcher独立，互不影响）：\n\n| 平台 | 数据量 | 降级方案 |\n|------|--------|---------|\n| 微博热搜 | 前50条 | 缓存兜底 |\n| 知乎热榜 | 前50条 | 第三方聚合 → 缓存兜底 |\n| B站热门 | 前100条 | 缓存兜底 |\n| 抖音热榜 | 前50条 | 第三方聚合 → 缓存兜底 |\n| 百度热搜 | 前50条 | 缓存兜底 |\n| 36氪热榜 | 前50条 | 缓存兜底 |\n| 少数派热榜 | 前40条 | 缓存兜底 |\n| 贴吧热议 | 前50条 | 缓存兜底 |\n\n**健壮机制**：\n- 每个请求最多重试3次，间隔递增（2s/4s/6s）\n- 主API失败自动切换降级方案\n- 所有方案失败则读取本地缓存（1小时内有效）\n- 每条数据经过字段校验，缺必要字段则丢弃\n- 抓取成功的数据自动缓存 + 按日归档\n\n数据将保存为 `./hot_lists.json` 文件，包含：\n- `version`: \"2.0\"\n- `timestamp`: 抓取时间\n- `platform_stats`: 各平台抓取状态\n- `data`: 所有热点数据（含评分字段）\n\n### 步骤2：结构化评分与筛选\n\n读取 `./hot_lists.json` 文件，脚本已自动完成评分，智能体需要：\n\n1. **确认数据完整性**：检查 `platform_stats`，记录哪些平台成功/降级/失败\n2. **选取TOP10**：按 `final_score` 降序取前10条\n3. **多样性校验**：检查10条热点的领域分布，同领域超过4条时，向下替换为其他领域高分热点\n4. **去重确认**：脚本已做跨平台语义归并，智能体需最终确认无重复\n\n**评分算法**：\n```\n综合得分 = 热度标准化分 × 0.4 + 跨平台共振分 × 0.5 + 基础分 10\n- 热度标准化：各平台热度归一化到 0-100\n- 跨平台共振：每多一个平台同时热议 +20 分\n- 基础分：保底 10 分，避免零分\n```\n\n**筛选标准**（优先级从高到低）：\n1. 跨平台共振（3平台以上同时热议 → 强入选信号）\n2. 热度绝对值（高热度但仅单平台 → 领域标志性事件）\n3. 话题多样性（科技/社会/娱乐/财经/文化/健康/体育 兼顾）\n4. 平台平衡（避免单平台超过4条入选）\n\n### 步骤3：生成三层洞察点评\n\n为每条选中的热点生成**三层洞察**，而非一句话点评：\n\n| 层级 | 含义 | 要求 |\n|------|------|------|\n| **What** | 事件本质（一句话定义） | 15-25字，直击核心，不加修饰 |\n| **So What** | 为什么重要（影响链） | 30-50字，分析因果与结构性影响 |\n| **Now What** | 后续关注什么（预判） | 20-35字，指出后续关键变量或时间节点 |\n\n**点评风格**：根据用户指定或默认选择\n\n| 风格 | 调性 | 触发词 |\n|------|------|--------|\n| **严肃分析**（默认） | 客观、专业、克制 | \"分析\"、\"严肃\"、或不指定 |\n| **毒舌吐槽** | 犀利、反讽、解构 | \"毒舌\"、\"吐槽\"、\"讽刺\" |\n| **投资视角** | 机会导向、数据驱动 | \"投资\"、\"股票\"、\"标的\" |\n| **吃瓜八卦** | 轻松、八卦、猎奇 | \"吃瓜\"、\"八卦\"、\"聊聊\" |\n\n**点评质量红线**：\n- What 禁止复述标题，必须是\"翻译\"后的本质\n- So What 禁止空洞判断（如\"引发广泛关注\"），必须有具体影响链条\n- Now What 禁止泛泛而谈，必须给出可验证的后续观察点\n- 全程避免主观臆断，基于已知事实推演\n\n### 步骤4：格式化输出\n\n根据用户需求选择输出格式，参见 [references/output-format.md](references/output-format.md)：\n\n| 格式 | 适用场景 | 触发词 |\n|------|---------|--------|\n| **群聊格式**（默认） | 微信/钉钉/飞书群 | 不指定、\"群聊\"、\"简洁\" |\n| **知识库格式** | Notion/Obsidian/语雀 | \"知识库\"、\"详细\"、\"归档\" |\n| **可视化看板** | 汇报演示/PPT | \"看板\"、\"图表\"、\"可视化\" |\n| **语音播报** | 通勤听热点 | \"语音\"、\"播报\"、\"听\" |\n\n若用户未指定格式，默认使用群聊格式。\n若用户未指定风格，默认使用严肃分析风格。\n\n输出末尾附加提示：\n> 如需详细版本，请说明\"知识库格式\"；如换口味，试试\"毒舌吐槽\"/\"投资视角\"/\"吃瓜八卦\"风格\n\n### 步骤5：数据清理\n\n- 处理完成后可删除 `./hot_lists.json` 临时文件\n- `./cache/` 目录保留，供下次降级使用\n- `./history/` 目录长期保留，供趋势分析使用\n\n## 资源索引\n- 数据抓取脚本：[scripts/hot_list_fetcher.py](scripts/hot_list_fetcher.py) - 插件化8平台抓取 + 评分模型 + 历史归档\n- 输出格式规范：[references/output-format.md](references/output-format.md) - 群聊/知识库/可视化看板/语音播报四种格式 + 四种点评风格\n\n## 扩展能力\n\n### 趋势分析（基于历史数据）\n当用户询问\"热点趋势\"、\"对比昨天\"、\"本周回顾\"时：\n1. 读取 `./history/` 目录下对应日期的数据\n2. 对比不同日期的热点变化（新进/退出/持续）\n3. 生成趋势分析报告\n\n### 定制化筛选\n当用户指定领域偏好时：\n- \"只看科技\" → 筛选时提高科技领域权重，其他领域降权\n- \"排除娱乐\" → 筛选时过滤娱乐类热点\n- \"只看投资机会\" → 自动切换投资视角风格\n\n## 注意事项\n- 数据抓取频率：建议每日最多执行2-3次，避免对平台服务器造成压力\n- 时效性：热榜数据变化快，建议在需要时实时抓取，不要使用过时数据\n- 内容合规：筛选热点时注意内容合规性，避免敏感话题\n- 降级透明：输出中必须标注各平台抓取状态（✅正常/⚠️降级/❌失败），让用户知道数据可信度\n- 评分可解释：每条热点附评分理由，用户可追溯筛选逻辑\n- 缓存有效期：默认1小时，超时自动重新抓取\n- 历史数据：按日归档，长期保留，不要自动清理', 1, 1, 0, '吴同', 2, '2026-06-25 20:58:39', '超级管理员', NULL, '2026-06-25 22:10:02', NULL);
INSERT INTO `kb_skills` VALUES (22, 1001, 'bid-tender-master', '输入项目名称和预算，AI自动生成完整投标文件。覆盖货物采购、服务项目、工程施工三大行业，自动分片生成，格式不乱、报价一致、自带废标风险自查。告别熬夜写标书。', '/skills/bid-tender-master', '# 标书大师｜全行业AI标书生成助手\n\n## 技能定位\n\n专业辅助制作国内招投标标书，覆盖货物采购、服务项目、工程施工三大类型。输入招标要求和公司资料，自动生成商务标、技术标、报价标全套内容。无需专业标书经验，小微企业也能做出专业标书。\n\n---\n\n# 一、快速上手｜直接复制这句话就能用\n\n### 生成完整标书\n```\n请帮我生成一份[货物采购/服务项目/工程施工]标书。\n项目名称：XXX\n预算金额：XXX万元\n投标单位：XXX公司\n工期要求：XXX天\n请包含商务标、技术标、报价标全套内容。\n```\n\n### 示例：工程类标书\n```\n请帮我生成一份工程施工标书。\n项目名称：XX市老旧小区改造工程（一期）\n预算金额：500万元\n投标单位：XX建设工程有限公司\n工期要求：120日历天\n质保期：2年\n```\n\n### 示例：货物采购类\n```\n请帮我生成一份货物采购标书。\n项目名称：XX中学多媒体教室设备采购\n预算金额：80万元\n投标单位：XX教育科技有限公司\n交货期：30天\n主要设备：智慧黑板20套、投影仪10台、音响系统5套\n```\n\n### 示例：服务项目类\n```\n请帮我生成一份服务项目标书。\n项目名称：XX园区物业管理服务\n预算金额：120万元/年\n投标单位：XX物业管理有限公司\n服务期限：1年\n服务范围：安保、保洁、绿化、维修\n```\n\n---\n\n# 二、核心能力\n\n### 1. 全流程出稿\n- 自动生成：投标函、授权委托书、商务标、技术标、报价表、偏离表全套内容\n- 三大行业：货物采购、服务项目、工程施工，各自专属模板\n\n### 2. 专业分片生成\n- 大型标书自动拆分章节，单次只做一个模块\n- 50–500页标书稳定输出，内容不丢、格式不乱、章节不串位\n- 目录、表格、标题格式全程锁定，复制到Word可直接排版\n\n### 3. 多重废标风控\n- 32项废标红线自查，自动高亮风险点\n- 报价大小写同步生成，不一致自动提醒\n- 负偏离自动标红标注\n- 全项自查：漏项检查、报价检查、偏离检查、必备条款检查\n\n### 4. 灵活修改\n- 支持单句润色、段落重写、章节局部调整\n- 改内容不用重写全文\n- 支持版本回滚\n\n### 5. 全局统一\n- 项目名称、编号、报价、工期等信息全文同步\n- 杜绝前后不一致的低级错误\n\n---\n\n# 三、常用修改指令\n\n### 修改报价\n```\n把报价改成450万元，大写金额同步更新。重新核对所有报价表的一致性。\n```\n\n### 调整技术方案\n```\n技术方案第三章施工进度安排太笼统，请补充详细的施工节点计划，按周列出关键里程碑。\n```\n\n### 补充内容\n```\n在商务标部分补充公司近3年同类项目业绩表，包括：项目名称、合同金额、业主单位、完工时间。\n```\n\n### 废标自查\n```\n请对已生成的标书进行废标风险自查，列出所有可能存在废标风险的地方。\n```\n\n### 分片生成（大型标书）\n```\n先帮我生成标书的大纲目录，然后分章节生成。先从商务标第一章开始。\n```\n\n---\n\n# 四、使用流程\n\n### 你需要提供\n1. 招标文件关键要求（或上传PDF招标文件）\n2. 项目名称、项目编号\n3. 投标单位信息（公司名称、资质等）\n4. 报价、工期/服务期、质保期\n5. 企业业绩、人员/资质/设备资料\n\n### 我会帮你做\n1. 解析招标文件，提取关键要求、评分项、禁止条款\n2. 按行业模板分章生成标书内容\n3. 自动校验报价一致性、格式规范性\n4. 标注偏离项和风险点\n5. 提供修改建议，支持多轮迭代\n\n---\n\n# 五、生成效果预览\n\n### 输入（货物采购示例）\n```\n项目名称：XX小学信息化设备采购\n预算：200万元\n投标单位：XX科技有限公司\n```\n\n### 输出结构\n```\n📄 商务标\n  ├── 投标函\n  ├── 法定代表人授权委托书\n  ├── 公司资质文件\n  ├── 近3年业绩表\n  └── 信誉承诺书\n\n📄 技术标\n  ├── 项目理解与总体方案\n  ├── 设备选型及技术参数\n  ├── 供货与安装方案\n  ├── 质量保证措施\n  ├── 培训与售后服务方案\n  └── 项目团队配置\n\n📄 报价标\n  ├── 报价汇总表\n  ├── 分项报价明细表（含大写金额）\n  ├── 设备参数响应/偏离表\n  └── 服务承诺报价\n```\n\n---\n\n# 六、合规声明\n\n本工具仅根据用户提供的真实资料标准化排版、撰写标书内容：\n- ❌ 不编造虚假资质、业绩、报价及人员信息\n- ❌ 不生成违规承诺\n- ✅ 内容最终由投标方自行审核、盖章确认后递交\n\n---\n\n# 七、适用人群\n\n- 投标工作室\n- 小微企业投标负责人\n- 行政采购人员\n- 工程服务商\n- 个人兼职投标人员\n\n---\n\n# 八、FAQ\n\n| 问题 | 回答 |\n|------|------|\n| 支持多少页标书？ | 小型标书可完整生成，50–500页大中型标书采用分片模式，稳定不崩。 |\n| 分哪些行业模板？ | 货物采购、服务项目、工程施工三大类，覆盖主流招投标行业。 |\n| 生成后可以修改吗？ | 支持任意局部润色、改数据、调表格、重写章节，支持撤销与版本恢复。 |\n| 报价大小写会自动核对吗？ | 报价自动生成大小写金额，不一致时主动提醒核对。 |\n| 可以上传招标文件吗？ | 支持上传PDF招标文件，自动提取关键要求、评分项、禁止条款。 |\n| 需要标书经验吗？ | 不需要。提供资料即可，AI按专业模板自动生成。 |\n\n---\n\n# 九、输出标识\n\n每条输出末尾固定：\n```\n⚠️ 本标书由AI辅助生成，所有数据、资质、报价、工期必须人工核对并盖章确认。\n标识：BD-MASTER-2.0.0\n```', 1, 1, 0, '吴同', 2, '2026-06-25 20:59:36', '吴同', NULL, '2026-06-25 22:38:30', NULL);
INSERT INTO `kb_skills` VALUES (23, 1001, 'pump-fault-detector', '当用户需要基于泵站运行数据生成故障检测报告时使用。支持接收传感器原始数据或人工录入数据，自动判断是否存在故障、定位可能的故障类型，并按模板输出规范的泵站故障检测报告。', '/skills/pump-fault-detector', '# 泵站故障检测\n\n## 概述\n\n本 skill 用于帮助用户根据泵站运行数据生成标准化的《泵站故障检测报告》。它会引导用户提供必要的泵站信息和运行数据，然后基于内置规则判断是否存在异常，并给出故障类型、可能原因、严重程度和处理建议。\n\n触发场景：\n- 用户提供了泵站传感器数据，要求分析是否故障\n- 用户要求生成泵站故障检测报告\n- 用户描述泵站异常现象，需要排查和定位故障\n- 用户输入如 \"帮我检测一下这个泵站的故障\"、\"生成泵站故障报告\"、\"分析一下水泵运行数据\" 等\n\n## 核心流程\n\n1. **识别意图**\n   当用户提到以下关键词或场景时触发：\n   - 泵站故障\n   - 水泵异常\n   - 故障检测 / 故障诊断\n   - 故障报告 / 检测报告\n   - 运行数据分析\n\n2. **收集必要信息**\n   每次优先问一个最关键的问题，最多一次问 2-3 个强相关问题。必须收集的信息包括：\n   - 泵站名称 / 编号\n   - 检测时间\n   - 水泵型号（可选）\n   - 运行数据：电流(A)、电压(V)、功率(kW)、流量(m³/h)、扬程(m)、转速(r/min)、振动速度(mm/s)、温度(℃)、轴承温度(℃)、进出口压力(MPa)、运行时长(h)\n   - 异常现象描述（可选）\n\n3. **执行故障判断**\n   基于用户提供的数据，按 `references/fault-rules.md` 中的规则进行判断：\n   - 单项指标越限\n   - 多项指标组合异常\n   - 与历史正常值对比\n   - 给出故障等级：正常 / 注意 / 异常 / 严重\n\n4. **生成故障检测报告**\n   使用 `references/report-template.md` 的模板输出报告，报告应包含：\n   - 基本信息\n   - 检测数据汇总\n   - 故障判断结果\n   - 故障类型与可能原因\n   - 处理建议\n   - 后续跟踪建议\n\n5. **输出格式**\n   - 默认输出 Markdown 格式报告\n   - 如用户需要，可输出为纯文本表格或结构化 JSON\n\n## 产品边界\n\n- 本 skill 仅做基于规则的故障辅助判断，不做实时控制系统联动\n- 输出报告为建议性文档，最终处置以现场工程师判断为准\n- 不提供设备维修操作指导以外的专业技术服务\n- 不涉及 API、数据库、字段类型等技术实现细节\n\n## 高频遗漏检查\n\n输出报告前检查是否包含：\n- 泵站名称和检测时间\n- 所有关键运行数据及单位\n- 明确的故障判断结论\n- 故障等级\n- 至少一项可能原因\n- 至少一项处理建议\n- 是否需要停机检修或继续观察\n\n## 资源\n\n### references/\n\n- [references/fault-rules.md](references/fault-rules.md)\n  泵站常见故障判断规则、指标阈值、故障等级定义。\n- [references/report-template.md](references/report-template.md)\n  标准泵站故障检测报告模板。\n- [references/sample-data.md](references/sample-data.md)\n  假数据示例，用于演示或测试报告生成效果。', 0, 1, 0, '吴同', 2, '2026-06-25 21:06:23', '吴同', NULL, '2026-06-25 17:00:42', NULL);

-- ----------------------------
-- Table structure for kb_agent_config
-- ----------------------------
DROP TABLE IF EXISTS `kb_agent_config`;
CREATE TABLE `kb_agent_config`  (
                                    `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
                                    `workspace_id` bigint(20) NOT NULL COMMENT '工作区id',
                                    `bot_id` bigint(20) NULL DEFAULT NULL COMMENT 'botid',
                                    `model_config` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '大模型配置',
                                    `pre_prompt` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '提示词',
                                    `parameters` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '参数配置',
                                    `knowledge_ids` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '知识库ids',
                                    `graph_ids` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '知识图谱ids',
                                    `tool_method_ids` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工具ids',
                                    `skill_ids` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'skill ids',
                                    `valid_flag` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否有效;0：无效，1：有效',
                                    `del_flag` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除标志;1：已删除，0：未删除',
                                    `create_by` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
                                    `creator_id` bigint(20) NULL DEFAULT NULL COMMENT '创建人id',
                                    `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                    `update_by` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
                                    `updater_id` bigint(20) NULL DEFAULT NULL COMMENT '更新人id',
                                    `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
                                    `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
                                    PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'agent配置' ROW_FORMAT = DYNAMIC;

